-- Ten short questions per published quiz; retain every historical version.
INSERT INTO quiz_versions(quiz_id,version,body,published_at) VALUES ('q001',2,'{"title":"On gagne plus avec les aides qu’en travaillant","intro":"« À quoi bon travailler si les aides rapportent plus ? » On regarde ce qui entre, ce qui sort et ce que les comparaisons oublient.","questions":[{"id":"q001-simple-01","prompt":"Comparer les aides d’une famille au salaire d’une personne seule, c’est fiable ?","choices":[{"id":"a","text":"Oui, si on compare les montants nets"},{"id":"b","text":"Non, il faut comparer des foyers semblables"},{"id":"c","text":"Oui, si les deux vivent dans la même ville"},{"id":"d","text":"Seulement si le salaire est au SMIC"}],"correctChoiceId":"b","explanation":"Le même budget ne fait pas vivre une personne ou cinq. Et une personne qui travaille peut aussi recevoir des aides.","nuance":"Le nombre de personnes à charge change beaucoup la comparaison.","sources":[{"publisher":"Insee","title":"Niveau de vie et revenu disponible — définitions","url":"https://www.insee.fr/fr/statistiques/1912151?sommaire=1912155","checkedAt":"2026-10-23"},{"publisher":"Service Public — DILA","title":"Prime d’activité : salarié ou fonctionnaire","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F2882","checkedAt":"2026-10-23"}]},{"id":"q001-simple-02","prompt":"Peut-on toucher une aide quand on travaille ?","choices":[{"id":"a","text":"Seulement avec des enfants"},{"id":"b","text":"Uniquement pendant la période d’essai"},{"id":"c","text":"Non, le salaire remplace toutes les aides"},{"id":"d","text":"Oui, comme la prime d’activité"}],"correctChoiceId":"d","explanation":"La prime d’activité complète certains petits revenus du travail. Oublier les aides du salarié fausse le calcul.","nuance":"Son montant dépend aussi des autres revenus du foyer.","sources":[{"publisher":"Service Public — DILA","title":"Prime d’activité : salarié ou fonctionnaire","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F2882","checkedAt":"2026-10-23"}]},{"id":"q001-simple-03","prompt":"Peut-on additionner le maximum de toutes les aides ?","choices":[{"id":"a","text":"Non, les aides peuvent se réduire entre elles"},{"id":"b","text":"Oui, si on fait toutes les demandes"},{"id":"c","text":"Oui, quand on n’a aucun salaire"},{"id":"d","text":"Seulement à partir de trois enfants"}],"correctChoiceId":"a","explanation":"Les montants affichés ne se cumulent pas tous. Certaines aides entrent dans le calcul des autres et en réduisent le montant.","nuance":"Il faut vérifier un cas réel, pas additionner des plafonds.","sources":[{"publisher":"Service Public — DILA","title":"Quelles sont les ressources prises en compte pour le calcul des droits au RSA ?","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F24585","checkedAt":"2026-10-23"}]},{"id":"q001-simple-04","prompt":"Toucher l’APL peut-il changer le montant du RSA ?","choices":[{"id":"a","text":"Non, les deux calculs sont indépendants"},{"id":"b","text":"Oui, le RSA augmente du même montant"},{"id":"c","text":"Oui, le calcul du RSA en tient compte"},{"id":"d","text":"Oui, on perd forcément tout le RSA"}],"correctChoiceId":"c","explanation":"Une somme forfaitaire liée au logement est prise en compte dans le RSA. Le RSA maximal et l’APL ne s’additionnent donc pas toujours tels quels.","nuance":"Cette somme n’est pas forcément égale à l’APL reçue.","sources":[{"publisher":"Service Public — DILA","title":"RSA : demandeur de 25 ans et plus — conditions et calcul","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F19778","checkedAt":"2026-10-23"}]},{"id":"q001-simple-05","prompt":"Ton conjoint travaille. Ses revenus comptent-ils pour ton RSA ?","choices":[{"id":"a","text":"Seulement si vous êtes mariés"},{"id":"b","text":"Seulement avec un compte bancaire commun"},{"id":"c","text":"Oui, même si vous n’êtes pas mariés"},{"id":"d","text":"Non, chacun a son propre calcul"}],"correctChoiceId":"c","explanation":"Le RSA regarde les ressources du foyer. Ne pas avoir de salaire personnel ne donne pas automatiquement droit au RSA maximal.","nuance":"Les autres aides n’ont pas forcément les mêmes règles.","sources":[{"publisher":"Service Public — DILA","title":"Quelles sont les ressources prises en compte pour le calcul des droits au RSA ?","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F24585","checkedAt":"2026-10-23"}]},{"id":"q001-simple-06","prompt":"Reprendre un emploi peut entraîner quels frais en plus ?","choices":[{"id":"a","text":"La garde des enfants et les trajets"},{"id":"b","text":"Seulement les impôts"},{"id":"c","text":"Seulement les repas"},{"id":"d","text":"Aucun, tout est remboursé"}],"correctChoiceId":"a","explanation":"Pour comparer les budgets, il faut aussi regarder les dépenses liées au travail. Elles peuvent absorber une partie du gain.","nuance":"On compare ici l’argent restant, pas seulement le revenu affiché.","sources":[{"publisher":"Insee","title":"Niveau de vie et revenu disponible — définitions","url":"https://www.insee.fr/fr/statistiques/1912151?sommaire=1912155","checkedAt":"2026-10-23"}]},{"id":"q001-simple-07","prompt":"Une hausse de salaire peut-elle faire baisser l’APL ?","choices":[{"id":"a","text":"Non, seul le loyer compte"},{"id":"b","text":"Oui, l’APL disparaît dès le premier salaire"},{"id":"c","text":"Seulement si on déménage"},{"id":"d","text":"Oui, selon les ressources retenues"}],"correctChoiceId":"d","explanation":"L’aide au logement dépend notamment des revenus. Une hausse de salaire peut donc modifier son montant.","nuance":"Cela ne signifie pas une suppression immédiate dans tous les cas.","sources":[{"publisher":"Service Public — DILA","title":"Aide personnalisée au logement (APL)","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F12006","checkedAt":"2026-10-23"}]},{"id":"q001-simple-08","prompt":"Deux salariés au même salaire touchent-ils la même prime d’activité ?","choices":[{"id":"a","text":"Oui, c’est un montant fixe par salaire"},{"id":"b","text":"Pas forcément, leur foyer compte aussi"},{"id":"c","text":"Oui, s’ils travaillent autant d’heures"},{"id":"d","text":"Seulement s’ils ont le même âge"}],"correctChoiceId":"b","explanation":"La prime dépend aussi des personnes à charge et des autres ressources du foyer. Un salaire identique ne suffit pas.","nuance":"Un exemple doit préciser la situation familiale.","sources":[{"publisher":"Service Public — DILA","title":"Prime d’activité : salarié ou fonctionnaire","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F2882","checkedAt":"2026-10-23"}]},{"id":"q001-simple-09","prompt":"Avoir droit au RSA, c’est forcément le toucher ?","choices":[{"id":"a","text":"Non, une partie des personnes éligibles ne le reçoit pas"},{"id":"b","text":"Oui, le versement est automatique"},{"id":"c","text":"Oui, dès qu’on n’a plus de salaire"},{"id":"d","text":"Non, seuls les nouveaux bénéficiaires le demandent"}],"correctChoiceId":"a","explanation":"La DREES estime qu’environ un tiers des foyers éligibles ne touchait pas le RSA fin 2021. Les droits possibles et l’argent reçu sont deux choses différentes.","nuance":"Étude publiée en 2026, sur la France métropolitaine et les logements ordinaires en 2021.","sources":[{"publisher":"DREES","title":"Non-recours au RSA : plus d’un tiers des foyers éligibles ne le percevaient pas fin 2021 — mai 2026","url":"https://drees.solidarites-sante.gouv.fr/sites/default/files/2026-05/ER1370_Non-recours_RSA.pdf","checkedAt":"2026-10-23"}]},{"id":"q001-simple-10","prompt":"Exemple : tu gagnes 200 € de plus, mais tu as 260 € de frais en plus. Il te reste…","choices":[{"id":"a","text":"60 € de plus"},{"id":"b","text":"200 € de plus"},{"id":"c","text":"60 € de moins"},{"id":"d","text":"260 € de moins"}],"correctChoiceId":"c","explanation":"Dans cet exemple, les frais supplémentaires dépassent le gain : 200 − 260 = −60 €. Cela peut changer l’intérêt financier d’un emploi.","nuance":"Exemple inventé, pas une règle générale sur les aides ou le travail.","sources":[{"publisher":"Insee","title":"Niveau de vie et revenu disponible — définitions","url":"https://www.insee.fr/fr/statistiques/1912151?sommaire=1912155","checkedAt":"2026-10-23"}]}]}','2026-10-24T11:15:00.000Z');
UPDATE quizzes SET outline='["Comparer les aides d’une famille au salaire d’une personne seule, c’est fiable ?", "Peut-on toucher une aide quand on travaille ?", "Peut-on additionner le maximum de toutes les aides ?", "Toucher l’APL peut-il changer le montant du RSA ?", "Ton conjoint travaille. Ses revenus comptent-ils pour ton RSA ?", "Reprendre un emploi peut entraîner quels frais en plus ?", "Une hausse de salaire peut-elle faire baisser l’APL ?", "Deux salariés au même salaire touchent-ils la même prime d’activité ?", "Avoir droit au RSA, c’est forcément le toucher ?", "Exemple : tu gagnes 200 € de plus, mais tu as 260 € de frais en plus. Il te reste…"]',current_version=2 WHERE id='q001';
INSERT INTO quiz_versions(quiz_id,version,body,published_at) VALUES ('q011',3,'{"title":"Les allocations ruinent la France","intro":"« On dépense tout pour les aides ! » Mais de quelles aides parle-t-on ? Dix questions pour remettre les montants à leur place.","questions":[{"id":"q011-simple-01","prompt":"Les dépenses sociales, c’est seulement l’argent versé aux personnes sans emploi ?","choices":[{"id":"a","text":"Oui, avec les aides au logement"},{"id":"b","text":"Non, cela inclut aussi retraites et santé"},{"id":"c","text":"Oui, sauf les allocations familiales"},{"id":"d","text":"Non, cela désigne seulement les retraites"}],"correctChoiceId":"b","explanation":"Les comptes de la protection sociale couvrent bien plus que les aides aux personnes sans emploi. Les retraites et la santé y occupent une grande place.","nuance":"Selon le tableau utilisé, la santé peut être présentée séparément.","sources":[{"publisher":"DREES","title":"La protection sociale en France et en Europe en 2024 — édition 2025","url":"https://www.drees.solidarites-sante.gouv.fr/sites/default/files/2025-12/La%20protection%20sociale%20en%20France%20et%20en%20Europe%20en%202024%20-%20R%C3%A9sultats%20des%20comptes%20de%20la%20protection%20sociale%20-%20%C3%89dition%202025.pdf","checkedAt":"2026-10-23"},{"publisher":"Insee","title":"Usage de l’argent public : les dépenses publiques par fonction en 2024 — Insee Première n° 2093","url":"https://www.insee.fr/fr/statistiques/8735252","checkedAt":"2026-10-23"}]},{"id":"q011-simple-02","prompt":"Qu’est-ce qui coûte le plus : les retraites ou le RSA ?","choices":[{"id":"a","text":"Le RSA, de très loin"},{"id":"b","text":"À peu près la même somme"},{"id":"c","text":"Cela change chaque mois"},{"id":"d","text":"Les retraites, de très loin"}],"correctChoiceId":"d","explanation":"Les retraites pèsent bien davantage. Dans les comptes DREES de 2024, vieillesse et décès représentent près de 46 % des prestations sociales.","nuance":"Ce poste comprend notamment les pensions de retraite et de réversion.","sources":[{"publisher":"DREES","title":"La protection sociale en France et en Europe en 2024 — édition 2025","url":"https://www.drees.solidarites-sante.gouv.fr/sites/default/files/2025-12/La%20protection%20sociale%20en%20France%20et%20en%20Europe%20en%202024%20-%20R%C3%A9sultats%20des%20comptes%20de%20la%20protection%20sociale%20-%20%C3%89dition%202025.pdf","checkedAt":"2026-10-23"}]},{"id":"q011-simple-03","prompt":"Tous les minima sociaux réunis coûtaient combien en 2024 ?","choices":[{"id":"a","text":"Environ 33 milliards d’euros"},{"id":"b","text":"Environ 3 milliards"},{"id":"c","text":"Environ 330 milliards"},{"id":"d","text":"Environ 900 milliards"}],"correctChoiceId":"a","explanation":"La DREES compte 33,3 milliards d’euros. Les minima sociaux sont les aides qui garantissent un revenu minimal, comme le RSA ou le minimum vieillesse.","nuance":"Ce total ne correspond pas au seul RSA.","sources":[{"publisher":"DREES","title":"Minima sociaux et prestations de solidarité — édition 2025","url":"https://drees.solidarites-sante.gouv.fr/publications-communique-de-presse/panoramas-de-la-drees/251204-minima-sociaux-et-prestations-de-solidarite","checkedAt":"2026-10-23"}]},{"id":"q011-simple-04","prompt":"Qui reçoit aussi un minimum social ?","choices":[{"id":"a","text":"Seulement les demandeurs d’emploi"},{"id":"b","text":"Seulement les parents sans emploi"},{"id":"c","text":"Des personnes âgées ou handicapées aux faibles ressources"},{"id":"d","text":"Seulement les personnes n’ayant jamais travaillé"}],"correctChoiceId":"c","explanation":"L’allocation aux adultes handicapés et le minimum vieillesse font aussi partie de ces aides. Leurs bénéficiaires n’ont pas tous la possibilité de travailler.","nuance":"On ne peut pas résumer toutes ces situations à un refus de travailler.","sources":[{"publisher":"Insee","title":"Allocataires de minima sociaux — données 2024, publication du 2 octobre 2026","url":"https://www.insee.fr/fr/statistiques/2411049","checkedAt":"2026-10-23"}]},{"id":"q011-simple-05","prompt":"Les minima sociaux représentent quel ordre de grandeur des dépenses publiques ?","choices":[{"id":"a","text":"Environ 20 %"},{"id":"b","text":"Environ 40 %"},{"id":"c","text":"Environ 2 %"},{"id":"d","text":"Environ 60 %"}],"correctChoiceId":"c","explanation":"Pour 2024, 33,3 milliards rapportés à environ 1 672 milliards donnent près de 2 %. On est loin du premier poste de dépense.","nuance":"C’est un ordre de grandeur tiré de deux publications, pas une nouvelle catégorie comptable officielle.","sources":[{"publisher":"DREES","title":"Minima sociaux et prestations de solidarité — édition 2025","url":"https://drees.solidarites-sante.gouv.fr/publications-communique-de-presse/panoramas-de-la-drees/251204-minima-sociaux-et-prestations-de-solidarite","checkedAt":"2026-10-23"},{"publisher":"Insee","title":"Usage de l’argent public : les dépenses publiques par fonction en 2024 — Insee Première n° 2093","url":"https://www.insee.fr/fr/statistiques/8735252","checkedAt":"2026-10-23"}]},{"id":"q011-simple-06","prompt":"En 2024, quel grand poste public coûtait le plus ?","choices":[{"id":"a","text":"La protection sociale, dont les retraites"},{"id":"b","text":"La défense"},{"id":"c","text":"L’enseignement"},{"id":"d","text":"Les intérêts de la dette"}],"correctChoiceId":"a","explanation":"La protection sociale arrive en tête dans le tableau de l’Insee. Cela ne veut pas dire que le RSA et les allocations familiales sont les plus grosses dépenses.","nuance":"Dans ce tableau, la santé est comptée à part.","sources":[{"publisher":"Insee","title":"Usage de l’argent public : les dépenses publiques par fonction en 2024 — Insee Première n° 2093","url":"https://www.insee.fr/fr/statistiques/8735252","checkedAt":"2026-10-23"}]},{"id":"q011-simple-07","prompt":"Un retraité qui a cotisé bénéficie-t-il quand même de la protection sociale ?","choices":[{"id":"a","text":"Non, puisque c’est son argent"},{"id":"b","text":"Seulement si sa retraite est petite"},{"id":"c","text":"Seulement s’il touche aussi l’APL"},{"id":"d","text":"Oui, sa retraite en fait partie"}],"correctChoiceId":"d","explanation":"La protection sociale comprend aussi les retraites financées par les cotisations. Elle ne se limite pas aux aides accordées sans cotisation passée.","nuance":"Retraite et RSA restent des dispositifs différents.","sources":[{"publisher":"DREES","title":"La protection sociale en France et en Europe en 2024 — édition 2025","url":"https://www.drees.solidarites-sante.gouv.fr/sites/default/files/2025-12/La%20protection%20sociale%20en%20France%20et%20en%20Europe%20en%202024%20-%20R%C3%A9sultats%20des%20comptes%20de%20la%20protection%20sociale%20-%20%C3%89dition%202025.pdf","checkedAt":"2026-10-23"}]},{"id":"q011-simple-08","prompt":"Faire une économie fait-il forcément baisser la dette ?","choices":[{"id":"a","text":"Oui, dès le premier euro économisé"},{"id":"b","text":"Non, on peut encore dépenser plus qu’on ne reçoit"},{"id":"c","text":"Non, la dette ne peut jamais baisser"},{"id":"d","text":"Oui, même si les recettes baissent davantage"}],"correctChoiceId":"b","explanation":"Une économie peut réduire le manque d’argent annuel sans le supprimer. Dans ce cas, la dette peut encore augmenter, mais moins vite.","nuance":"Cela suppose que les autres recettes et dépenses ne changent pas.","sources":[{"publisher":"Ministère de l’Économie","title":"Décryptage : 5 minutes pour comprendre la dette publique","url":"https://www.economie.gouv.fr/decryptage-5-minutes-pour-comprendre-la-dette-publique","checkedAt":"2026-10-23"}]},{"id":"q011-simple-09","prompt":"Le déficit augmente. Est-ce forcément la faute des allocations ?","choices":[{"id":"a","text":"Non, les recettes et les autres dépenses comptent aussi"},{"id":"b","text":"Oui, ce sont les seules dépenses variables"},{"id":"c","text":"Oui, si le nombre de retraités augmente"},{"id":"d","text":"Non, seuls les intérêts comptent"}],"correctChoiceId":"a","explanation":"Pour trouver la cause, il faut regarder ce qui a changé dans les dépenses et les recettes. Un déficit ne désigne pas tout seul son responsable.","nuance":"Un chiffre global ne suffit pas à accuser une aide précise.","sources":[{"publisher":"Ministère de l’Économie","title":"Décryptage : 5 minutes pour comprendre la dette publique","url":"https://www.economie.gouv.fr/decryptage-5-minutes-pour-comprendre-la-dette-publique","checkedAt":"2026-10-23"}]},{"id":"q011-simple-10","prompt":"Les aides font-elles réellement reculer la pauvreté ?","choices":[{"id":"a","text":"Non, elles ne changent rien"},{"id":"b","text":"Oui, elles la suppriment presque entièrement"},{"id":"c","text":"Oui, sans la faire disparaître"},{"id":"d","text":"Seulement pour les retraités"}],"correctChoiceId":"c","explanation":"Pour 2022, la DREES estime que les prestations étudiées et les impôts directs font passer le taux de pauvreté de 21,3 % à 14,4 %.","nuance":"Cette comparaison ne prévoit pas tous les effets qu’aurait leur suppression.","sources":[{"publisher":"DREES","title":"Minima sociaux et prestations de solidarité — édition 2025","url":"https://drees.solidarites-sante.gouv.fr/publications-communique-de-presse/panoramas-de-la-drees/251204-minima-sociaux-et-prestations-de-solidarite","checkedAt":"2026-10-23"}]}]}','2026-10-24T11:15:00.000Z');
UPDATE quizzes SET outline='["Les dépenses sociales, c’est seulement l’argent versé aux personnes sans emploi ?", "Qu’est-ce qui coûte le plus : les retraites ou le RSA ?", "Tous les minima sociaux réunis coûtaient combien en 2024 ?", "Qui reçoit aussi un minimum social ?", "Les minima sociaux représentent quel ordre de grandeur des dépenses publiques ?", "En 2024, quel grand poste public coûtait le plus ?", "Un retraité qui a cotisé bénéficie-t-il quand même de la protection sociale ?", "Faire une économie fait-il forcément baisser la dette ?", "Le déficit augmente. Est-ce forcément la faute des allocations ?", "Les aides font-elles réellement reculer la pauvreté ?"]',current_version=3 WHERE id='q011';
INSERT INTO quiz_versions(quiz_id,version,body,published_at) VALUES ('q014',2,'{"title":"La dette vient forcément d’un excès de dépenses","intro":"« Si on a des dettes, c’est qu’on dépense trop. » Dépenses, recettes, intérêts : on regarde ce qui fait vraiment bouger la dette.","questions":[{"id":"q014-simple-01","prompt":"L’État dépense plus qu’il ne reçoit cette année. C’est…","choices":[{"id":"a","text":"Une dette effacée"},{"id":"b","text":"Un déficit"},{"id":"c","text":"Un excédent"},{"id":"d","text":"Une baisse des prix"}],"correctChoiceId":"b","explanation":"Le déficit est l’écart entre dépenses et recettes sur une période. La dette correspond à un montant accumulé.","nuance":"Une année de déficit et le total de la dette ne sont pas la même chose.","sources":[{"publisher":"Insee","title":"Le compte des administrations publiques en 2025","url":"https://www.insee.fr/fr/statistiques/8997691","checkedAt":"2026-10-23"}]},{"id":"q014-simple-02","prompt":"Si les recettes baissent et les dépenses restent stables, le déficit…","choices":[{"id":"a","text":"Diminue"},{"id":"b","text":"Ne change pas"},{"id":"c","text":"Disparaît"},{"id":"d","text":"Se creuse"}],"correctChoiceId":"d","explanation":"Il manque davantage d’argent pour payer les mêmes dépenses. Un déficit peut donc augmenter sans nouvelle hausse des dépenses.","nuance":"C’est un exemple à dépenses constantes, pas le récit de toutes les années.","sources":[{"publisher":"Insee","title":"Le compte des administrations publiques en 2025","url":"https://www.insee.fr/fr/statistiques/8997691","checkedAt":"2026-10-23"}]},{"id":"q014-simple-03","prompt":"Une baisse d’impôts peut-elle creuser le déficit ?","choices":[{"id":"a","text":"Oui, si rien ne compense les recettes perdues"},{"id":"b","text":"Non, les impôts ne financent pas les dépenses"},{"id":"c","text":"Non, elle se rembourse toujours toute seule"},{"id":"d","text":"Seulement si les retraites augmentent"}],"correctChoiceId":"a","explanation":"Moins de recettes, sans baisse des dépenses ni autre compensation, creuse l’écart. Il faut examiner les deux côtés du budget.","nuance":"Les effets sur l’activité peuvent aussi modifier les recettes.","sources":[{"publisher":"Insee","title":"Le compte des administrations publiques en 2025","url":"https://www.insee.fr/fr/statistiques/8997691","checkedAt":"2026-10-23"}]},{"id":"q014-simple-04","prompt":"La dette publique, c’est seulement la dette de l’État ?","choices":[{"id":"a","text":"Oui, uniquement celle des ministères"},{"id":"b","text":"Non, elle inclut tous les crédits des ménages"},{"id":"c","text":"Non, elle inclut aussi d’autres administrations"},{"id":"d","text":"Oui, sauf pendant les crises"}],"correctChoiceId":"c","explanation":"Elle comprend notamment l’État, les administrations locales et celles de sécurité sociale.","nuance":"Les dettes privées des habitants n’y sont pas ajoutées.","sources":[{"publisher":"Insee","title":"Le compte des administrations publiques en 2025","url":"https://www.insee.fr/fr/statistiques/8997691","checkedAt":"2026-10-23"}]},{"id":"q014-simple-05","prompt":"Quand l’État emprunte, l’argent est-il gratuit ?","choices":[{"id":"a","text":"Oui, puisqu’il crée tous les euros"},{"id":"b","text":"Oui, si le prêteur est français"},{"id":"c","text":"Non, il paie généralement des intérêts"},{"id":"d","text":"Non, il rembourse toujours le double"}],"correctChoiceId":"c","explanation":"Le taux et la durée de l’emprunt déterminent son coût. Les intérêts occupent une place dans le budget.","nuance":"Le taux d’un nouvel emprunt ne s’applique pas d’un coup à toute la dette ancienne.","sources":[{"publisher":"Ministère de l’Économie","title":"Décryptage : 5 minutes pour comprendre la dette publique","url":"https://www.economie.gouv.fr/decryptage-5-minutes-pour-comprendre-la-dette-publique","checkedAt":"2026-10-23"}]},{"id":"q014-simple-06","prompt":"Rembourser un ancien emprunt avec un nouveau, ça existe ?","choices":[{"id":"a","text":"Oui, l’État refinance ainsi une partie de sa dette"},{"id":"b","text":"Non, c’est interdit aux États"},{"id":"c","text":"Seulement en cas de faillite"},{"id":"d","text":"Oui, et cela annule la dette"}],"correctChoiceId":"a","explanation":"Quand une dette arrive à échéance, l’État peut emprunter pour la rembourser. Le créancier change, mais la dette ne disparaît pas.","nuance":"Ce mécanisme n’explique pas à lui seul pourquoi le montant total augmente.","sources":[{"publisher":"Ministère de l’Économie","title":"Décryptage : 5 minutes pour comprendre la dette publique","url":"https://www.economie.gouv.fr/decryptage-5-minutes-pour-comprendre-la-dette-publique","checkedAt":"2026-10-23"}]},{"id":"q014-simple-07","prompt":"« La dette vaut 100 % du PIB » : ça veut dire quoi ?","choices":[{"id":"a","text":"Tout le revenu des habitants sera saisi"},{"id":"b","text":"L’État ne peut plus emprunter"},{"id":"c","text":"Les dépenses publiques ont doublé"},{"id":"d","text":"Elle vaut une année de production du pays"}],"correctChoiceId":"d","explanation":"Le PIB sert de point de comparaison : il mesure la richesse produite pendant une année. Ce n’est pas la caisse de l’État.","nuance":"100 % n’est pas un seuil qui déclenche automatiquement une faillite.","sources":[{"publisher":"Ministère de l’Économie","title":"Décryptage : 5 minutes pour comprendre la dette publique","url":"https://www.economie.gouv.fr/decryptage-5-minutes-pour-comprendre-la-dette-publique","checkedAt":"2026-10-23"}]},{"id":"q014-simple-08","prompt":"La production augmente, la dette reste stable. Le ratio dette/PIB…","choices":[{"id":"a","text":"Monte"},{"id":"b","text":"Baisse"},{"id":"c","text":"Reste forcément identique"},{"id":"d","text":"Devient forcément nul"}],"correctChoiceId":"b","explanation":"Le même montant de dette pèse moins face à une production plus élevée. Le rapport dépend aussi de ce qui se passe dans l’économie.","nuance":"Le montant en euros peut rester stable pendant que le pourcentage baisse.","sources":[{"publisher":"Ministère de l’Économie","title":"Décryptage : 5 minutes pour comprendre la dette publique","url":"https://www.economie.gouv.fr/decryptage-5-minutes-pour-comprendre-la-dette-publique","checkedAt":"2026-10-23"}]},{"id":"q014-simple-09","prompt":"Une dépense publique est-elle forcément perdue ?","choices":[{"id":"a","text":"Non, elle peut financer un service ou un investissement"},{"id":"b","text":"Oui, contrairement à une dépense privée"},{"id":"c","text":"Oui, sauf si elle rembourse une dette"},{"id":"d","text":"Non, elle rapporte toujours plus qu’elle ne coûte"}],"correctChoiceId":"a","explanation":"Les dépenses financent des usages différents : services, prestations ou investissements. Leur montant ne dit pas à lui seul leur utilité.","nuance":"Une dépense utile peut aussi être mal conçue ou trop coûteuse.","sources":[{"publisher":"Insee","title":"Le compte des administrations publiques en 2025","url":"https://www.insee.fr/fr/statistiques/8997691","checkedAt":"2026-10-23"}]},{"id":"q014-simple-10","prompt":"Pour expliquer la dette, que faut-il regarder ?","choices":[{"id":"a","text":"Seulement le nombre de fonctionnaires"},{"id":"b","text":"Seulement le montant du RSA"},{"id":"c","text":"Les dépenses, les recettes et l’activité économique"},{"id":"d","text":"Seulement les dépenses de l’année"}],"correctChoiceId":"c","explanation":"Le déficit dépend des dépenses et des recettes ; le poids de la dette dépend aussi de l’économie. Une seule cause ne suffit pas à tout expliquer.","nuance":"Il faut préciser la période et les choix budgétaires dont on parle.","sources":[{"publisher":"Insee","title":"Le compte des administrations publiques en 2025","url":"https://www.insee.fr/fr/statistiques/8997691","checkedAt":"2026-10-23"}]}]}','2026-10-24T11:15:00.000Z');
UPDATE quizzes SET outline='["L’État dépense plus qu’il ne reçoit cette année. C’est…", "Si les recettes baissent et les dépenses restent stables, le déficit…", "Une baisse d’impôts peut-elle creuser le déficit ?", "La dette publique, c’est seulement la dette de l’État ?", "Quand l’État emprunte, l’argent est-il gratuit ?", "Rembourser un ancien emprunt avec un nouveau, ça existe ?", "« La dette vaut 100 % du PIB » : ça veut dire quoi ?", "La production augmente, la dette reste stable. Le ratio dette/PIB…", "Une dépense publique est-elle forcément perdue ?", "Pour expliquer la dette, que faut-il regarder ?"]',current_version=2 WHERE id='q014';
INSERT INTO quiz_versions(quiz_id,version,body,published_at) VALUES ('q016',2,'{"title":"La moitié des Français ne paie aucun impôt","intro":"« La moitié des gens ne paie rien. » Mais de quel impôt parle-t-on ? On suit les taxes dans la vie de tous les jours.","questions":[{"id":"q016-simple-01","prompt":"Ne pas payer d’impôt sur le revenu, c’est ne payer aucun impôt ?","choices":[{"id":"a","text":"Oui, c’est une exonération générale"},{"id":"b","text":"Non, on peut en payer d’autres"},{"id":"c","text":"Oui, si on n’est pas propriétaire"},{"id":"d","text":"Seulement quand on est retraité"}],"correctChoiceId":"b","explanation":"L’impôt sur le revenu n’est qu’un impôt parmi d’autres. La TVA est par exemple comprise dans de nombreux achats.","nuance":"Il faut nommer l’impôt avant de comparer les contribuables.","sources":[{"publisher":"Service Public","title":"Calcul de l’impôt sur le revenu","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F34328","checkedAt":"2026-10-23"},{"publisher":"Direction générale des douanes","title":"Taxe sur la valeur ajoutée","url":"https://www.douane.gouv.fr/lexique/taxe-sur-la-valeur-ajoutee-tva","checkedAt":"2026-10-23"}]},{"id":"q016-simple-02","prompt":"Quand tu achètes un produit soumis à la TVA, qui la paie au final ?","choices":[{"id":"a","text":"Uniquement le magasin"},{"id":"b","text":"Uniquement le fabricant"},{"id":"c","text":"Seulement les clients imposables"},{"id":"d","text":"Le consommateur"}],"correctChoiceId":"d","explanation":"La TVA est comprise dans le prix payé. L’entreprise la collecte et la reverse selon les règles applicables.","nuance":"Elle peut être peu visible parce qu’elle n’arrive pas dans un avis d’impôt.","sources":[{"publisher":"Direction générale des douanes","title":"Taxe sur la valeur ajoutée","url":"https://www.douane.gouv.fr/lexique/taxe-sur-la-valeur-ajoutee-tva","checkedAt":"2026-10-23"}]},{"id":"q016-simple-03","prompt":"Une personne sans emploi paie-t-elle de la TVA sur ses achats ?","choices":[{"id":"a","text":"Oui, si les achats sont soumis à la TVA"},{"id":"b","text":"Non, le chômage l’en exonère"},{"id":"c","text":"Seulement si elle reçoit une allocation"},{"id":"d","text":"Seulement au-delà d’un revenu minimum"}],"correctChoiceId":"a","explanation":"La TVA sur un achat ne dépend pas du fait d’avoir un emploi. Elle dépend du produit ou du service acheté.","nuance":"Certains achats sont exonérés ou soumis à des taux différents.","sources":[{"publisher":"Direction générale des douanes","title":"Taxe sur la valeur ajoutée","url":"https://www.douane.gouv.fr/lexique/taxe-sur-la-valeur-ajoutee-tva","checkedAt":"2026-10-23"}]},{"id":"q016-simple-04","prompt":"Un salaire modeste entraîne-t-il forcément un impôt sur le revenu ?","choices":[{"id":"a","text":"Oui, dès le premier euro gagné"},{"id":"b","text":"Oui, pour toute personne à temps plein"},{"id":"c","text":"Non, le calcul peut aboutir à zéro"},{"id":"d","text":"Non, les salariés en sont tous exonérés"}],"correctChoiceId":"c","explanation":"Le calcul tient compte du revenu imposable et de la situation du foyer. Un salaire ne signifie pas automatiquement un impôt à payer.","nuance":"Ce n’est pas une exonération de toutes les autres taxes.","sources":[{"publisher":"DGFiP","title":"Comprendre le barème progressif de l’impôt","url":"https://www.impots.gouv.fr/particulier/questions/comment-calculer-mon-taux-dimposition-dapres-le-bareme-progressif-de-limpot","checkedAt":"2026-10-24"}]},{"id":"q016-simple-05","prompt":"L’impôt sur le revenu regarde-t-il aussi la famille ?","choices":[{"id":"a","text":"Non, seul le métier compte"},{"id":"b","text":"Seulement le nombre de personnes qui travaillent"},{"id":"c","text":"Oui, la composition du foyer compte"},{"id":"d","text":"Seulement si le couple est propriétaire"}],"correctChoiceId":"c","explanation":"Le nombre de parts intervient dans le calcul. Deux foyers avec le même revenu total peuvent donc avoir des impôts différents.","nuance":"Les effets dépendent de leur situation et des plafonds prévus.","sources":[{"publisher":"DGFiP","title":"Comprendre le barème progressif de l’impôt","url":"https://www.impots.gouv.fr/particulier/questions/comment-calculer-mon-taux-dimposition-dapres-le-bareme-progressif-de-limpot","checkedAt":"2026-10-24"}]},{"id":"q016-simple-06","prompt":"Ne pas payer d’impôt sur le revenu dispense-t-il toujours de taxe foncière ?","choices":[{"id":"a","text":"Non, ce n’est pas automatique"},{"id":"b","text":"Oui, pour tous les propriétaires"},{"id":"c","text":"Oui, même pour une résidence secondaire"},{"id":"d","text":"Seulement si le logement est loué"}],"correctChoiceId":"a","explanation":"La taxe foncière concerne les propriétaires, avec ses propres exonérations. L’absence d’impôt sur le revenu ne suffit pas à elle seule.","nuance":"Des allègements existent selon les ressources et d’autres conditions.","sources":[{"publisher":"Service Public","title":"Taxe foncière sur les propriétés bâties","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F59","checkedAt":"2026-10-24"}]},{"id":"q016-simple-07","prompt":"Un locataire paie-t-il directement la taxe foncière de son logement ?","choices":[{"id":"a","text":"Oui, dès qu’il a un salaire"},{"id":"b","text":"Oui, si le propriétaire vit ailleurs"},{"id":"c","text":"Seulement si le loyer dépasse un plafond"},{"id":"d","text":"Non, elle est due par le propriétaire"}],"correctChoiceId":"d","explanation":"Le propriétaire est redevable de la taxe foncière. Certaines charges distinctes peuvent toutefois être récupérées sur le locataire.","nuance":"La taxe d’enlèvement des ordures ménagères suit des règles particulières.","sources":[{"publisher":"Service Public","title":"Taxe foncière sur les propriétés bâties","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F59","checkedAt":"2026-10-24"}]},{"id":"q016-simple-08","prompt":"La taxe d’habitation a-t-elle disparu pour tous les logements ?","choices":[{"id":"a","text":"Oui, depuis 2023 pour tous"},{"id":"b","text":"Non, elle subsiste notamment pour les résidences secondaires"},{"id":"c","text":"Non, elle reste sur toutes les résidences principales"},{"id":"d","text":"Oui, sauf pour les locataires"}],"correctChoiceId":"b","explanation":"Elle a été supprimée sur les résidences principales. Cela ne signifie pas la fin de toute taxe d’habitation.","nuance":"Une résidence secondaire peut encore être concernée, même sans impôt sur le revenu.","sources":[{"publisher":"DGFiP","title":"Taxe d’habitation : qui est concerné en 2026 ?","url":"https://www.impots.gouv.fr/particulier/questions/je-suis-non-imposable-limpot-sur-le-revenu-vais-je-payer-une-taxe-dhabitation","checkedAt":"2026-10-24"}]},{"id":"q016-simple-09","prompt":"« 50 % des foyers » et « 50 % des personnes », c’est pareil ?","choices":[{"id":"a","text":"Non, un foyer peut réunir plusieurs personnes"},{"id":"b","text":"Oui, un foyer désigne toujours un adulte"},{"id":"c","text":"Oui, si on parle d’impôts"},{"id":"d","text":"Non, un foyer désigne toujours un couple"}],"correctChoiceId":"a","explanation":"L’impôt sur le revenu est calculé par foyer fiscal. Compter des foyers ne revient donc pas à compter chaque habitant.","nuance":"Le chiffre de 50 % est ici un exemple, pas une estimation pour une année précise.","sources":[{"publisher":"DGFiP","title":"Comprendre le barème progressif de l’impôt","url":"https://www.impots.gouv.fr/particulier/questions/comment-calculer-mon-taux-dimposition-dapres-le-bareme-progressif-de-limpot","checkedAt":"2026-10-24"}]},{"id":"q016-simple-10","prompt":"Pour vérifier « ils ne paient rien », quelle précision manque d’abord ?","choices":[{"id":"a","text":"Leur banque"},{"id":"b","text":"Leur moyen de paiement"},{"id":"c","text":"De quel impôt on parle"},{"id":"d","text":"Le jour où ils font leurs courses"}],"correctChoiceId":"c","explanation":"Ne pas payer un impôt précis ne veut pas dire ne contribuer à aucune recette publique. La TVA suffit à montrer la différence.","nuance":"Cela ne dit pas si la répartition des impôts est juste : c’est une autre question.","sources":[{"publisher":"Service Public","title":"Calcul de l’impôt sur le revenu","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F34328","checkedAt":"2026-10-23"},{"publisher":"Direction générale des douanes","title":"Taxe sur la valeur ajoutée","url":"https://www.douane.gouv.fr/lexique/taxe-sur-la-valeur-ajoutee-tva","checkedAt":"2026-10-23"}]}]}','2026-10-24T11:15:00.000Z');
UPDATE quizzes SET outline='["Ne pas payer d’impôt sur le revenu, c’est ne payer aucun impôt ?", "Quand tu achètes un produit soumis à la TVA, qui la paie au final ?", "Une personne sans emploi paie-t-elle de la TVA sur ses achats ?", "Un salaire modeste entraîne-t-il forcément un impôt sur le revenu ?", "L’impôt sur le revenu regarde-t-il aussi la famille ?", "Ne pas payer d’impôt sur le revenu dispense-t-il toujours de taxe foncière ?", "Un locataire paie-t-il directement la taxe foncière de son logement ?", "La taxe d’habitation a-t-elle disparu pour tous les logements ?", "« 50 % des foyers » et « 50 % des personnes », c’est pareil ?", "Pour vérifier « ils ne paient rien », quelle précision manque d’abord ?"]',current_version=2 WHERE id='q016';
INSERT INTO quiz_versions(quiz_id,version,body,published_at) VALUES ('q017',2,'{"title":"Une augmentation peut faire perdre de l’argent en changeant de tranche","intro":"« Si je gagne plus, je change de tranche et je perds de l’argent. » On teste cette idée avec des exemples tout simples.","questions":[{"id":"q017-simple-01","prompt":"Tu passes dans une tranche d’impôt plus élevée. Le nouveau taux frappe…","choices":[{"id":"a","text":"Tout ton salaire"},{"id":"b","text":"Seulement la partie concernée de ton revenu"},{"id":"c","text":"Tous les revenus gagnés depuis janvier au taux maximal"},{"id":"d","text":"Seulement les revenus de ton conjoint"}],"correctChoiceId":"b","explanation":"Le barème fonctionne par morceaux. Chaque tranche de revenu est taxée à son propre taux.","nuance":"On parle ici du barème de l’impôt, pas de toutes les aides qui dépendent des revenus.","sources":[{"publisher":"DGFiP","title":"Comprendre le barème progressif de l’impôt","url":"https://www.impots.gouv.fr/particulier/questions/comment-calculer-mon-taux-dimposition-dapres-le-bareme-progressif-de-limpot","checkedAt":"2026-10-24"}]},{"id":"q017-simple-02","prompt":"Les tranches d’impôt ressemblent plutôt à…","choices":[{"id":"a","text":"Un taux unique choisi pour tout le revenu"},{"id":"b","text":"Une taxe fixe pour chaque profession"},{"id":"c","text":"Un taux choisi par l’employeur"},{"id":"d","text":"Des étages qu’on remplit l’un après l’autre"}],"correctChoiceId":"d","explanation":"La partie basse du revenu garde son taux lorsque la partie haute entre dans une nouvelle tranche.","nuance":"Le calcul complet tient aussi compte du foyer fiscal.","sources":[{"publisher":"DGFiP","title":"Comprendre le barème progressif de l’impôt","url":"https://www.impots.gouv.fr/particulier/questions/comment-calculer-mon-taux-dimposition-dapres-le-bareme-progressif-de-limpot","checkedAt":"2026-10-24"}]},{"id":"q017-simple-03","prompt":"Exemple : 100 € de plus sont taxés à 30 %. Combien reste-t-il ?","choices":[{"id":"a","text":"70 €"},{"id":"b","text":"30 €"},{"id":"c","text":"0 €"},{"id":"d","text":"100 €"}],"correctChoiceId":"a","explanation":"Dans cet exemple simplifié, l’impôt supplémentaire est de 30 €. Il reste donc 70 € sur ces 100 € de revenu imposable en plus.","nuance":"On laisse de côté cotisations, aides et autres effets pour isoler le barème.","sources":[{"publisher":"DGFiP","title":"Taux moyen et taux marginal d’imposition","url":"https://www.impots.gouv.fr/particulier/questions/quoi-correspondent-le-taux-moyen-et-le-taux-marginal-dimposition-affiches-sur","checkedAt":"2026-10-24"}]},{"id":"q017-simple-04","prompt":"Passer dans une nouvelle tranche fait-il perdre tout le gain, à lui seul ?","choices":[{"id":"a","text":"Oui, à chaque changement de tranche"},{"id":"b","text":"Oui, dès la deuxième tranche"},{"id":"c","text":"Non, le taux supérieur ne frappe qu’une partie du revenu"},{"id":"d","text":"Seulement si on est célibataire"}],"correctChoiceId":"c","explanation":"Le changement de tranche ne transforme pas le taux supérieur en prélèvement sur tout le revenu.","nuance":"Une baisse d’aide peut modifier le budget, mais ce n’est pas le même mécanisme.","sources":[{"publisher":"DGFiP","title":"Comprendre le barème progressif de l’impôt","url":"https://www.impots.gouv.fr/particulier/questions/comment-calculer-mon-taux-dimposition-dapres-le-bareme-progressif-de-limpot","checkedAt":"2026-10-24"}]},{"id":"q017-simple-05","prompt":"Ton taux le plus élevé est-il forcément ton taux moyen ?","choices":[{"id":"a","text":"Oui, ce sont deux noms pour le même taux"},{"id":"b","text":"Oui, sauf pour les retraités"},{"id":"c","text":"Non, les parties basses sont moins taxées"},{"id":"d","text":"Non, le taux moyen est toujours plus élevé"}],"correctChoiceId":"c","explanation":"Le taux marginal concerne la tranche la plus haute. Le taux moyen rapporte l’impôt à l’ensemble du revenu imposable.","nuance":"Le mot « taux » ne suffit pas : il faut préciser lequel.","sources":[{"publisher":"DGFiP","title":"Taux moyen et taux marginal d’imposition","url":"https://www.impots.gouv.fr/particulier/questions/quoi-correspondent-le-taux-moyen-et-le-taux-marginal-dimposition-affiches-sur","checkedAt":"2026-10-24"}]},{"id":"q017-simple-06","prompt":"Exemple : 1 000 € d’impôt pour 20 000 € imposables. Le taux moyen est…","choices":[{"id":"a","text":"5 %"},{"id":"b","text":"20 %"},{"id":"c","text":"10 %"},{"id":"d","text":"50 %"}],"correctChoiceId":"a","explanation":"1 000 divisé par 20 000 donne 5 %. C’est la part du revenu imposable consacrée à cet impôt dans cet exemple.","nuance":"Ces montants sont inventés pour expliquer le calcul.","sources":[{"publisher":"DGFiP","title":"Taux moyen et taux marginal d’imposition","url":"https://www.impots.gouv.fr/particulier/questions/quoi-correspondent-le-taux-moyen-et-le-taux-marginal-dimposition-affiches-sur","checkedAt":"2026-10-24"}]},{"id":"q017-simple-07","prompt":"Le taux affiché sur ta fiche de paie résume-t-il toutes tes tranches ?","choices":[{"id":"a","text":"Oui, c’est toujours le taux de la dernière tranche"},{"id":"b","text":"Oui, c’est le même taux pour tous les salariés"},{"id":"c","text":"Non, c’est uniquement une cotisation retraite"},{"id":"d","text":"Non, c’est le taux de prélèvement à la source"}],"correctChoiceId":"d","explanation":"Le prélèvement à la source sert à collecter l’impôt au fil de l’année. Son taux ne se confond pas avec celui de la dernière tranche.","nuance":"La déclaration permet ensuite de calculer et régulariser l’impôt dû.","sources":[{"publisher":"DGFiP","title":"Taux moyen et taux marginal d’imposition","url":"https://www.impots.gouv.fr/particulier/questions/quoi-correspondent-le-taux-moyen-et-le-taux-marginal-dimposition-affiches-sur","checkedAt":"2026-10-24"}]},{"id":"q017-simple-08","prompt":"Deux personnes avec le même salaire ont-elles forcément le même impôt ?","choices":[{"id":"a","text":"Oui, le salaire suffit à tout calculer"},{"id":"b","text":"Non, leur situation familiale peut changer le calcul"},{"id":"c","text":"Oui, si elles ont le même employeur"},{"id":"d","text":"Non, leur ville fixe le barème"}],"correctChoiceId":"b","explanation":"Le revenu du foyer et le nombre de parts interviennent dans le calcul. Le seul salaire individuel ne donne pas toute l’information.","nuance":"D’autres revenus et certains avantages fiscaux peuvent aussi compter.","sources":[{"publisher":"DGFiP","title":"Comprendre le barème progressif de l’impôt","url":"https://www.impots.gouv.fr/particulier/questions/comment-calculer-mon-taux-dimposition-dapres-le-bareme-progressif-de-limpot","checkedAt":"2026-10-24"}]},{"id":"q017-simple-09","prompt":"Une aide qui baisse après une hausse de salaire, c’est le changement de tranche ?","choices":[{"id":"a","text":"Non, l’aide a ses propres règles"},{"id":"b","text":"Oui, les deux sont toujours liés"},{"id":"c","text":"Oui, toutes les aides suivent le barème de l’impôt"},{"id":"d","text":"Non, aucune aide ne dépend des revenus"}],"correctChoiceId":"a","explanation":"Une aide au logement peut varier avec les ressources. Il faut distinguer ce calcul de celui de l’impôt sur le revenu.","nuance":"Pour savoir ce qu’il reste, il faut regarder l’ensemble du budget.","sources":[{"publisher":"Service Public — DILA","title":"Aide personnalisée au logement (APL)","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F12006","checkedAt":"2026-10-23"}]},{"id":"q017-simple-10","prompt":"Avant de refuser une augmentation, quel calcul est utile ?","choices":[{"id":"a","text":"Appliquer le taux le plus haut à tout le salaire"},{"id":"b","text":"Regarder uniquement le nom de la tranche"},{"id":"c","text":"Comparer le revenu final et les aides avant et après"},{"id":"d","text":"Soustraire toute l’augmentation du salaire actuel"}],"correctChoiceId":"c","explanation":"Le barème ne suffit pas à mesurer le budget disponible. Une comparaison complète prend aussi en compte les autres changements.","nuance":"Les exemples du quiz expliquent le mécanisme, pas une situation personnelle.","sources":[{"publisher":"Insee","title":"Niveau de vie et revenu disponible — définitions","url":"https://www.insee.fr/fr/statistiques/1912151?sommaire=1912155","checkedAt":"2026-10-23"},{"publisher":"Service Public — DILA","title":"Prime d’activité : salarié ou fonctionnaire","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F2882","checkedAt":"2026-10-23"}]}]}','2026-10-24T11:15:00.000Z');
UPDATE quizzes SET outline='["Tu passes dans une tranche d’impôt plus élevée. Le nouveau taux frappe…", "Les tranches d’impôt ressemblent plutôt à…", "Exemple : 100 € de plus sont taxés à 30 %. Combien reste-t-il ?", "Passer dans une nouvelle tranche fait-il perdre tout le gain, à lui seul ?", "Ton taux le plus élevé est-il forcément ton taux moyen ?", "Exemple : 1 000 € d’impôt pour 20 000 € imposables. Le taux moyen est…", "Le taux affiché sur ta fiche de paie résume-t-il toutes tes tranches ?", "Deux personnes avec le même salaire ont-elles forcément le même impôt ?", "Une aide qui baisse après une hausse de salaire, c’est le changement de tranche ?", "Avant de refuser une augmentation, quel calcul est utile ?"]',current_version=2 WHERE id='q017';
INSERT INTO quiz_versions(quiz_id,version,body,published_at) VALUES ('q019',2,'{"title":"La TVA est juste puisque tout le monde paie le même taux","intro":"« Même taux, même effort. » La TVA touche tout le monde, mais pèse-t-elle autant dans tous les budgets ?","questions":[{"id":"q019-simple-01","prompt":"Deux clients achètent le même produit au même prix. La TVA change selon leur salaire ?","choices":[{"id":"a","text":"Oui, elle augmente avec le salaire"},{"id":"b","text":"Non, pas sur cet achat"},{"id":"c","text":"Oui, elle disparaît pour les non-imposables"},{"id":"d","text":"Seulement pour les retraités"}],"correctChoiceId":"b","explanation":"Pour un même achat soumis au même taux, le montant de TVA est identique. Le revenu du client ne modifie pas le ticket.","nuance":"Cela ne veut pas dire que cette somme pèse autant dans chaque budget.","sources":[{"publisher":"Ministère de l’Économie","title":"TVA : les taux du quotidien","url":"https://www.economie.gouv.fr/particuliers/impots-et-fiscalite/gerer-mes-autres-impots-et-taxes/tva-quels-sont-les-taux-de-votre-quotidien","checkedAt":"2026-10-23"}]},{"id":"q019-simple-02","prompt":"Tous les produits ont-ils le même taux de TVA ?","choices":[{"id":"a","text":"Oui, sans exception"},{"id":"b","text":"Non, chaque magasin invente ses taux"},{"id":"c","text":"Oui, sauf les achats en ligne"},{"id":"d","text":"Non, plusieurs taux existent"}],"correctChoiceId":"d","explanation":"La France applique plusieurs taux selon les biens et services. Le taux normal ne couvre pas tous les achats.","nuance":"Il existe aussi des exonérations et des règles territoriales particulières.","sources":[{"publisher":"Ministère de l’Économie","title":"TVA : les taux du quotidien","url":"https://www.economie.gouv.fr/particuliers/impots-et-fiscalite/gerer-mes-autres-impots-et-taxes/tva-quels-sont-les-taux-de-votre-quotidien","checkedAt":"2026-10-23"}]},{"id":"q019-simple-03","prompt":"Certains produits alimentaires ont-ils un taux réduit ?","choices":[{"id":"a","text":"Oui, beaucoup sont à taux réduit"},{"id":"b","text":"Non, tout est au taux normal"},{"id":"c","text":"Oui, mais uniquement en grande surface"},{"id":"d","text":"Seulement s’ils sont fabriqués en France"}],"correctChoiceId":"a","explanation":"De nombreux produits alimentaires bénéficient d’un taux réduit. Mais toutes les formes de restauration et tous les produits ne suivent pas la même règle.","nuance":"Un taux réduit n’est pas une absence de TVA.","sources":[{"publisher":"Ministère de l’Économie","title":"TVA : les taux du quotidien","url":"https://www.economie.gouv.fr/particuliers/impots-et-fiscalite/gerer-mes-autres-impots-et-taxes/tva-quels-sont-les-taux-de-votre-quotidien","checkedAt":"2026-10-23"}]},{"id":"q019-simple-04","prompt":"Le sigle « TTC » sur un prix veut dire…","choices":[{"id":"a","text":"Taxe totalement compensée"},{"id":"b","text":"Tarif transport compris"},{"id":"c","text":"Toutes taxes comprises"},{"id":"d","text":"Total transféré au commerçant"}],"correctChoiceId":"c","explanation":"Le prix TTC comprend les taxes applicables, dont la TVA. C’est généralement ce que le consommateur paie.","nuance":"Le prix hors taxes et le prix payé ne sont donc pas la même chose.","sources":[{"publisher":"Direction générale des douanes","title":"Taxe sur la valeur ajoutée","url":"https://www.douane.gouv.fr/lexique/taxe-sur-la-valeur-ajoutee-tva","checkedAt":"2026-10-23"}]},{"id":"q019-simple-05","prompt":"Un produit coûte 100 € hors taxes, avec 20 % de TVA. Tu paies…","choices":[{"id":"a","text":"100 €"},{"id":"b","text":"80 €"},{"id":"c","text":"120 €"},{"id":"d","text":"125 €"}],"correctChoiceId":"c","explanation":"La taxe vaut 20 % de 100 €, soit 20 €. Le prix total est donc de 120 €.","nuance":"C’est un exemple avec un taux de 20 %, pas le taux de tous les produits.","sources":[{"publisher":"Ministère de l’Économie","title":"TVA : les taux du quotidien","url":"https://www.economie.gouv.fr/particuliers/impots-et-fiscalite/gerer-mes-autres-impots-et-taxes/tva-quels-sont-les-taux-de-votre-quotidien","checkedAt":"2026-10-23"}]},{"id":"q019-simple-06","prompt":"Sur ce prix de 120 € TTC, quelle somme correspond à la TVA ?","choices":[{"id":"a","text":"20 €"},{"id":"b","text":"24 €"},{"id":"c","text":"100 €"},{"id":"d","text":"12 €"}],"correctChoiceId":"a","explanation":"Les 20 % s’appliquent au prix hors taxes de 100 €, pas au prix final de 120 €.","nuance":"Il faut savoir sur quelle base un pourcentage est calculé.","sources":[{"publisher":"Ministère de l’Économie","title":"TVA : les taux du quotidien","url":"https://www.economie.gouv.fr/particuliers/impots-et-fiscalite/gerer-mes-autres-impots-et-taxes/tva-quels-sont-les-taux-de-votre-quotidien","checkedAt":"2026-10-23"}]},{"id":"q019-simple-07","prompt":"100 € de taxes pèsent-ils autant avec 1 000 € et 3 000 € de revenu ?","choices":[{"id":"a","text":"Oui, puisque le montant est identique"},{"id":"b","text":"Oui, si les achats sont identiques"},{"id":"c","text":"Non, ils prennent une plus grande part des 3 000 €"},{"id":"d","text":"Non, ils prennent une plus grande part des 1 000 €"}],"correctChoiceId":"d","explanation":"100 € représentent 10 % de 1 000 €, contre environ 3,3 % de 3 000 €. Même montant ne veut pas dire même effort relatif.","nuance":"Exemple fictif pour comparer des parts de budget.","sources":[{"publisher":"Direction générale des douanes","title":"Taxe sur la valeur ajoutée","url":"https://www.douane.gouv.fr/lexique/taxe-sur-la-valeur-ajoutee-tva","checkedAt":"2026-10-23"}]},{"id":"q019-simple-08","prompt":"Toucher un petit salaire exonère-t-il de TVA à la caisse ?","choices":[{"id":"a","text":"Oui, avec un justificatif de salaire"},{"id":"b","text":"Non, le taux dépend de l’achat"},{"id":"c","text":"Oui, si on touche la prime d’activité"},{"id":"d","text":"Seulement pour les dépenses du week-end"}],"correctChoiceId":"b","explanation":"La TVA ne fonctionne pas comme l’impôt progressif sur le revenu. Le magasin n’adapte pas son taux au salaire du client.","nuance":"Les taux réduits ciblent des produits ou services, pas le revenu de chaque client.","sources":[{"publisher":"Ministère de l’Économie","title":"TVA : les taux du quotidien","url":"https://www.economie.gouv.fr/particuliers/impots-et-fiscalite/gerer-mes-autres-impots-et-taxes/tva-quels-sont-les-taux-de-votre-quotidien","checkedAt":"2026-10-23"}]},{"id":"q019-simple-09","prompt":"Peut-on juger l’effort fiscal total avec la seule TVA ?","choices":[{"id":"a","text":"Non, d’autres impôts et transferts comptent aussi"},{"id":"b","text":"Oui, elle remplace tous les autres impôts"},{"id":"c","text":"Oui, car tout le monde consomme"},{"id":"d","text":"Non, la TVA n’est pas un impôt"}],"correctChoiceId":"a","explanation":"La TVA ne décrit qu’une partie des prélèvements. Il faut aussi regarder les autres impôts et les aides pour comparer des situations.","nuance":"Le choix de ce qu’on mesure doit être explicite.","sources":[{"publisher":"Service Public","title":"Calcul de l’impôt sur le revenu","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F34328","checkedAt":"2026-10-23"},{"publisher":"Direction générale des douanes","title":"Taxe sur la valeur ajoutée","url":"https://www.douane.gouv.fr/lexique/taxe-sur-la-valeur-ajoutee-tva","checkedAt":"2026-10-23"}]},{"id":"q019-simple-10","prompt":"« Juste », pour un impôt, est-ce seulement une question de taux ?","choices":[{"id":"a","text":"Oui, un taux identique prouve tout"},{"id":"b","text":"Oui, un taux réduit règle toutes les inégalités"},{"id":"c","text":"Non, cela dépend aussi du critère de justice choisi"},{"id":"d","text":"Non, les taux n’ont aucune importance"}],"correctChoiceId":"c","explanation":"Même montant, même part du revenu ou effort selon les moyens : ces critères ne donnent pas toujours le même résultat.","nuance":"Les règles fiscales sont des faits ; le critère de justice doit être discuté.","sources":[{"publisher":"Ministère de l’Économie","title":"TVA : les taux du quotidien","url":"https://www.economie.gouv.fr/particuliers/impots-et-fiscalite/gerer-mes-autres-impots-et-taxes/tva-quels-sont-les-taux-de-votre-quotidien","checkedAt":"2026-10-23"}]}]}','2026-10-24T11:15:00.000Z');
UPDATE quizzes SET outline='["Deux clients achètent le même produit au même prix. La TVA change selon leur salaire ?", "Tous les produits ont-ils le même taux de TVA ?", "Certains produits alimentaires ont-ils un taux réduit ?", "Le sigle « TTC » sur un prix veut dire…", "Un produit coûte 100 € hors taxes, avec 20 % de TVA. Tu paies…", "Sur ce prix de 120 € TTC, quelle somme correspond à la TVA ?", "100 € de taxes pèsent-ils autant avec 1 000 € et 3 000 € de revenu ?", "Toucher un petit salaire exonère-t-il de TVA à la caisse ?", "Peut-on juger l’effort fiscal total avec la seule TVA ?", "« Juste », pour un impôt, est-ce seulement une question de taux ?"]',current_version=2 WHERE id='q019';
INSERT INTO quiz_versions(quiz_id,version,body,published_at) VALUES ('q022',2,'{"title":"Être riche, c’est avoir un gros salaire","intro":"« Il gagne bien sa vie, donc il est riche. » Salaire, logement, dettes et héritage : on sépare ce qu’on gagne de ce qu’on possède.","questions":[{"id":"q022-simple-01","prompt":"Un salaire et un patrimoine, c’est la même chose ?","choices":[{"id":"a","text":"Oui, ce sont deux mots pour l’épargne"},{"id":"b","text":"Non, l’un est un revenu, l’autre ce qu’on possède"},{"id":"c","text":"Oui, si on gagne beaucoup"},{"id":"d","text":"Non, le patrimoine désigne seulement les maisons"}],"correctChoiceId":"b","explanation":"Un revenu arrive pendant une période. Le patrimoine est un ensemble de biens et d’actifs détenus à un moment donné.","nuance":"On peut avoir un revenu élevé et peu de patrimoine, ou l’inverse.","sources":[{"publisher":"Insee","title":"Patrimoine net des ménages","url":"https://www.insee.fr/fr/statistiques/5371259?sommaire=5371304","checkedAt":"2026-10-23"}]},{"id":"q022-simple-02","prompt":"Un appartement dont tu es propriétaire entre-t-il dans ton patrimoine ?","choices":[{"id":"a","text":"Seulement si tu le loues"},{"id":"b","text":"Seulement si tu l’as hérité"},{"id":"c","text":"Non, seul l’argent en banque compte"},{"id":"d","text":"Oui, même si tu y habites"}],"correctChoiceId":"d","explanation":"L’immobilier fait partie du patrimoine. La résidence principale compte donc aussi.","nuance":"Un emprunt restant à rembourser réduit le patrimoine net.","sources":[{"publisher":"Insee","title":"Patrimoine net des ménages","url":"https://www.insee.fr/fr/statistiques/5371259?sommaire=5371304","checkedAt":"2026-10-23"}]},{"id":"q022-simple-03","prompt":"Une maison vaut 200 000 €, avec 150 000 € de crédit restant. Le patrimoine net lié vaut…","choices":[{"id":"a","text":"50 000 €"},{"id":"b","text":"200 000 €"},{"id":"c","text":"350 000 €"},{"id":"d","text":"150 000 €"}],"correctChoiceId":"a","explanation":"On retranche la dette à la valeur du bien : 200 000 − 150 000 = 50 000 €.","nuance":"Exemple simplifié, sans frais de vente ni autres biens ou dettes.","sources":[{"publisher":"Insee","title":"Patrimoine net des ménages","url":"https://www.insee.fr/fr/statistiques/5371259?sommaire=5371304","checkedAt":"2026-10-23"}]},{"id":"q022-simple-04","prompt":"« Patrimoine net », ça veut dire…","choices":[{"id":"a","text":"Seulement l’argent sur le compte courant"},{"id":"b","text":"Le salaire après impôt"},{"id":"c","text":"Ce qu’on possède moins ce qu’on doit"},{"id":"d","text":"La valeur des biens sans retirer les dettes"}],"correctChoiceId":"c","explanation":"Le patrimoine net tient compte des dettes. Le patrimoine brut les laisse de côté.","nuance":"Comparer du brut et du net peut fortement fausser une comparaison.","sources":[{"publisher":"Insee","title":"Patrimoine net des ménages","url":"https://www.insee.fr/fr/statistiques/5371259?sommaire=5371304","checkedAt":"2026-10-23"}]},{"id":"q022-simple-05","prompt":"Un héritage peut-il augmenter ton patrimoine sans hausse de salaire ?","choices":[{"id":"a","text":"Non, seul le travail crée du patrimoine"},{"id":"b","text":"Seulement si tu vends les biens reçus"},{"id":"c","text":"Oui"},{"id":"d","text":"Non, un bien hérité ne compte pas"}],"correctChoiceId":"c","explanation":"Un bien reçu peut entrer dans le patrimoine sans modifier le salaire. Les deux indicateurs racontent des choses différentes.","nuance":"Les dettes et les droits éventuels doivent aussi être pris en compte.","sources":[{"publisher":"Insee","title":"Les montants de patrimoine détenus par les ménages en 2024","url":"https://www.insee.fr/fr/statistiques/8672665","checkedAt":"2026-10-24"}]},{"id":"q022-simple-06","prompt":"Peut-on avoir beaucoup de patrimoine et peu d’argent disponible ?","choices":[{"id":"a","text":"Oui, par exemple avec un logement de grande valeur"},{"id":"b","text":"Non, tous les biens se dépensent immédiatement"},{"id":"c","text":"Seulement si on est salarié"},{"id":"d","text":"Non, la banque verse la valeur du logement chaque mois"}],"correctChoiceId":"a","explanation":"Une maison ne se transforme pas instantanément en argent disponible. Il faut distinguer la valeur possédée et les liquidités.","nuance":"Cela n’enlève pas la valeur économique du bien.","sources":[{"publisher":"Insee","title":"Les montants de patrimoine détenus par les ménages en 2024","url":"https://www.insee.fr/fr/statistiques/8672665","checkedAt":"2026-10-24"}]},{"id":"q022-simple-07","prompt":"Les 10 % les mieux dotés possèdent-ils 10 % du patrimoine brut total ?","choices":[{"id":"a","text":"Oui, par définition"},{"id":"b","text":"Non, ils en possèdent moins de 10 %"},{"id":"c","text":"Oui, si on retire les milliardaires"},{"id":"d","text":"Non, ils en possèdent près de la moitié"}],"correctChoiceId":"d","explanation":"Début 2024, l’Insee estime que les 10 % de ménages les mieux dotés détiennent près de la moitié du patrimoine brut total.","nuance":"Champ de l’étude : ménages en logement ordinaire, France hors Mayotte.","sources":[{"publisher":"Insee","title":"Les montants de patrimoine détenus par les ménages en 2024","url":"https://www.insee.fr/fr/statistiques/8672665","checkedAt":"2026-10-24"}]},{"id":"q022-simple-08","prompt":"Un « patrimoine moyen » décrit-il forcément le ménage du milieu ?","choices":[{"id":"a","text":"Oui, moyenne et milieu sont identiques"},{"id":"b","text":"Non, les très gros patrimoines tirent la moyenne vers le haut"},{"id":"c","text":"Oui, si l’échantillon est grand"},{"id":"d","text":"Non, la moyenne ignore les plus riches"}],"correctChoiceId":"b","explanation":"La médiane sépare les ménages en deux moitiés. La moyenne additionne les montants puis les divise par le nombre de ménages.","nuance":"Ces indicateurs répondent à deux questions différentes.","sources":[{"publisher":"Insee","title":"Distribution du patrimoine des ménages","url":"https://www.insee.fr/fr/statistiques/2388851","checkedAt":"2026-10-24"}]},{"id":"q022-simple-09","prompt":"Un loyer reçu par un propriétaire est-il un salaire ?","choices":[{"id":"a","text":"Non, c’est un autre type de revenu"},{"id":"b","text":"Oui, tout argent reçu est un salaire"},{"id":"c","text":"Oui, si le propriétaire travaille aussi"},{"id":"d","text":"Non, ce n’est jamais un revenu"}],"correctChoiceId":"a","explanation":"On peut recevoir des revenus liés à des biens, en plus ou à la place d’un salaire. « Revenu » est plus large que « salaire ».","nuance":"Posséder un bien et toucher un revenu grâce à ce bien restent deux mesures distinctes.","sources":[{"publisher":"Insee","title":"Les montants de patrimoine détenus par les ménages en 2024","url":"https://www.insee.fr/fr/statistiques/8672665","checkedAt":"2026-10-24"}]},{"id":"q022-simple-10","prompt":"Pour comparer la richesse de deux personnes, le salaire suffit-il ?","choices":[{"id":"a","text":"Oui, s’il s’agit du salaire net"},{"id":"b","text":"Oui, si elles ont le même âge"},{"id":"c","text":"Non, il faut aussi regarder leurs biens et leurs dettes"},{"id":"d","text":"Non, seul leur compte courant compte"}],"correctChoiceId":"c","explanation":"Le salaire renseigne sur une entrée d’argent. Le patrimoine net renseigne sur ce qui reste après les dettes.","nuance":"Une comparaison précise tient aussi compte de la taille du foyer et des besoins.","sources":[{"publisher":"Insee","title":"Patrimoine net des ménages","url":"https://www.insee.fr/fr/statistiques/5371259?sommaire=5371304","checkedAt":"2026-10-23"}]}]}','2026-10-24T11:15:00.000Z');
UPDATE quizzes SET outline='["Un salaire et un patrimoine, c’est la même chose ?", "Un appartement dont tu es propriétaire entre-t-il dans ton patrimoine ?", "Une maison vaut 200 000 €, avec 150 000 € de crédit restant. Le patrimoine net lié vaut…", "« Patrimoine net », ça veut dire…", "Un héritage peut-il augmenter ton patrimoine sans hausse de salaire ?", "Peut-on avoir beaucoup de patrimoine et peu d’argent disponible ?", "Les 10 % les mieux dotés possèdent-ils 10 % du patrimoine brut total ?", "Un « patrimoine moyen » décrit-il forcément le ménage du milieu ?", "Un loyer reçu par un propriétaire est-il un salaire ?", "Pour comparer la richesse de deux personnes, le salaire suffit-il ?"]',current_version=2 WHERE id='q022';
INSERT INTO quiz_versions(quiz_id,version,body,published_at) VALUES ('q029',2,'{"title":"Les dividendes sont une récompense versée aux salariés","intro":"« Les dividendes, c’est une prime pour ceux qui travaillent. » On regarde qui les touche, qui décide et ce que cela change.","questions":[{"id":"q029-simple-01","prompt":"Pour toucher un dividende d’une entreprise, il faut d’abord…","choices":[{"id":"a","text":"Y travailler à temps plein"},{"id":"b","text":"Détenir une part de cette entreprise"},{"id":"c","text":"Être son client depuis un an"},{"id":"d","text":"Être son dirigeant salarié"}],"correctChoiceId":"b","explanation":"Un dividende est lié à la détention de parts ou d’actions. Il n’est pas versé parce qu’on a travaillé un certain nombre d’heures.","nuance":"Un salarié peut aussi être actionnaire, mais ce sont deux rôles différents.","sources":[{"publisher":"Ministère de l’Économie","title":"Dictionnaire de l’économie : action et dividendes","url":"https://www.economie.gouv.fr/facileco/dico-de-leco","checkedAt":"2026-10-23"}]},{"id":"q029-simple-02","prompt":"Peut-on toucher un dividende sans travailler dans l’entreprise ?","choices":[{"id":"a","text":"Non, il faut un contrat de travail"},{"id":"b","text":"Seulement si on est retraité"},{"id":"c","text":"Seulement après dix ans d’ancienneté"},{"id":"d","text":"Oui, si on en détient des parts et qu’elle en verse"}],"correctChoiceId":"d","explanation":"Le droit au dividende vient des parts détenues. Un actionnaire extérieur à l’entreprise peut donc en recevoir.","nuance":"Détenir une action ne garantit pas un versement.","sources":[{"publisher":"Ministère de l’Économie","title":"Comment acheter des actions","url":"https://www.economie.gouv.fr/particuliers/gerer-mon-argent/gerer-mon-budget-et-mon-epargne/comment-acheter-des-actions","checkedAt":"2026-10-24"}]},{"id":"q029-simple-03","prompt":"Un salarié touche-t-il automatiquement les dividendes de son entreprise ?","choices":[{"id":"a","text":"Non, son statut de salarié ne suffit pas"},{"id":"b","text":"Oui, en fin d’année"},{"id":"c","text":"Oui, après la période d’essai"},{"id":"d","text":"Seulement s’il travaille le dimanche"}],"correctChoiceId":"a","explanation":"Le salaire paie le travail. Le dividende revient aux détenteurs de parts quand une distribution est décidée.","nuance":"Des dispositifs de partage des bénéfices existent séparément.","sources":[{"publisher":"Ministère de l’Économie","title":"Dictionnaire de l’économie : action et dividendes","url":"https://www.economie.gouv.fr/facileco/dico-de-leco","checkedAt":"2026-10-23"}]},{"id":"q029-simple-04","prompt":"Une entreprise qui fait des bénéfices doit-elle tout distribuer ?","choices":[{"id":"a","text":"Oui, c’est obligatoire"},{"id":"b","text":"Oui, sauf si elle est petite"},{"id":"c","text":"Non, elle peut en conserver une partie"},{"id":"d","text":"Non, elle doit tout verser aux salariés"}],"correctChoiceId":"c","explanation":"Les bénéfices ne sont pas automatiquement distribués en totalité. Une décision de distribution intervient selon les règles de la société.","nuance":"Conserver des bénéfices peut notamment servir à financer l’activité.","sources":[{"publisher":"Service Public Entreprendre","title":"Fiscalité des dividendes perçus par les associés","url":"https://entreprendre.service-public.gouv.fr/vosdroits/F32963","checkedAt":"2026-10-24"}]},{"id":"q029-simple-05","prompt":"Qui décide généralement de la distribution des bénéfices ?","choices":[{"id":"a","text":"Les clients par un vote en ligne"},{"id":"b","text":"L’administration fiscale chaque mois"},{"id":"c","text":"Les associés ou actionnaires réunis en assemblée"},{"id":"d","text":"Les salariés uniquement"}],"correctChoiceId":"c","explanation":"Dans une société, la décision est prise selon les règles de l’assemblée des associés ou actionnaires.","nuance":"Le dirigeant ne peut pas simplement confondre la trésorerie de la société avec son argent personnel.","sources":[{"publisher":"Service Public Entreprendre","title":"Fiscalité des dividendes perçus par les associés","url":"https://entreprendre.service-public.gouv.fr/vosdroits/F32963","checkedAt":"2026-10-24"}]},{"id":"q029-simple-06","prompt":"Acheter une action garantit-il un revenu chaque année ?","choices":[{"id":"a","text":"Non, le dividende n’est pas garanti"},{"id":"b","text":"Oui, comme un salaire mensuel"},{"id":"c","text":"Oui, même si l’entreprise ne distribue rien"},{"id":"d","text":"Seulement si l’achat se fait en ligne"}],"correctChoiceId":"a","explanation":"Une entreprise peut ne pas verser de dividende. Le cours de l’action peut aussi baisser.","nuance":"Un placement en actions comporte un risque de perte.","sources":[{"publisher":"Ministère de l’Économie","title":"Comment acheter des actions","url":"https://www.economie.gouv.fr/particuliers/gerer-mon-argent/gerer-mon-budget-et-mon-epargne/comment-acheter-des-actions","checkedAt":"2026-10-24"}]},{"id":"q029-simple-07","prompt":"Revendre une action plus cher, est-ce toucher un dividende ?","choices":[{"id":"a","text":"Oui, c’est exactement pareil"},{"id":"b","text":"Oui, si on la garde plus d’un an"},{"id":"c","text":"Non, ce gain est un salaire"},{"id":"d","text":"Non, c’est une plus-value"}],"correctChoiceId":"d","explanation":"Le dividende est un versement lié à l’action. La plus-value est le gain réalisé en la revendant plus cher qu’à l’achat.","nuance":"On peut aussi revendre à perte.","sources":[{"publisher":"Ministère de l’Économie","title":"Comment acheter des actions","url":"https://www.economie.gouv.fr/particuliers/gerer-mon-argent/gerer-mon-budget-et-mon-epargne/comment-acheter-des-actions","checkedAt":"2026-10-24"}]},{"id":"q029-simple-08","prompt":"La participation des salariés, c’est quoi ?","choices":[{"id":"a","text":"Le nom français du dividende"},{"id":"b","text":"Un dispositif de partage des bénéfices avec les salariés"},{"id":"c","text":"Une baisse obligatoire du salaire"},{"id":"d","text":"Un prêt fait par les clients"}],"correctChoiceId":"b","explanation":"La participation peut attribuer une part des bénéfices aux salariés, selon ses règles. Elle est distincte des dividendes.","nuance":"Tous les salariés bénéficiaires n’ont pas besoin d’être actionnaires.","sources":[{"publisher":"Service Public","title":"Participation : le partage des bénéfices avec les salariés","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F2141","checkedAt":"2026-10-24"}]},{"id":"q029-simple-09","prompt":"La participation peut-elle remplacer le salaire prévu ?","choices":[{"id":"a","text":"Non, elle vient en complément"},{"id":"b","text":"Oui, si l’entreprise est rentable"},{"id":"c","text":"Oui, avec un paiement annuel"},{"id":"d","text":"Seulement pour les nouveaux salariés"}],"correctChoiceId":"a","explanation":"La participation est un complément lié aux résultats. Elle ne se substitue pas à la rémunération prévue.","nuance":"Son montant peut varier d’une année à l’autre.","sources":[{"publisher":"Service Public","title":"Participation : le partage des bénéfices avec les salariés","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F2141","checkedAt":"2026-10-24"}]},{"id":"q029-simple-10","prompt":"Un salarié actionnaire peut-il toucher salaire et dividendes ?","choices":[{"id":"a","text":"Non, il doit choisir"},{"id":"b","text":"Seulement s’il dirige l’entreprise"},{"id":"c","text":"Oui, au titre de ses deux rôles"},{"id":"d","text":"Non, les dividendes sont réservés aux banques"}],"correctChoiceId":"c","explanation":"Son salaire rémunère son travail. Ses dividendes éventuels sont liés aux parts qu’il détient.","nuance":"Cela ne signifie pas que tous les salariés détiennent des actions.","sources":[{"publisher":"Ministère de l’Économie","title":"Dictionnaire de l’économie : action et dividendes","url":"https://www.economie.gouv.fr/facileco/dico-de-leco","checkedAt":"2026-10-23"}]}]}','2026-10-24T11:15:00.000Z');
UPDATE quizzes SET outline='["Pour toucher un dividende d’une entreprise, il faut d’abord…", "Peut-on toucher un dividende sans travailler dans l’entreprise ?", "Un salarié touche-t-il automatiquement les dividendes de son entreprise ?", "Une entreprise qui fait des bénéfices doit-elle tout distribuer ?", "Qui décide généralement de la distribution des bénéfices ?", "Acheter une action garantit-il un revenu chaque année ?", "Revendre une action plus cher, est-ce toucher un dividende ?", "La participation des salariés, c’est quoi ?", "La participation peut-elle remplacer le salaire prévu ?", "Un salarié actionnaire peut-il toucher salaire et dividendes ?"]',current_version=2 WHERE id='q029';
INSERT INTO quiz_versions(quiz_id,version,body,published_at) VALUES ('q031',2,'{"title":"Les chômeurs ne veulent pas travailler","intro":"« S’ils voulaient travailler, ils trouveraient. » On regarde ce que les chiffres disent vraiment des personnes sans emploi.","questions":[{"id":"q031-simple-01","prompt":"Dans les chiffres de l’Insee, un chômeur doit-il chercher un emploi ?","choices":[{"id":"a","text":"Non, il suffit de ne pas travailler"},{"id":"b","text":"Oui, ou avoir déjà un emploi qui commence bientôt"},{"id":"c","text":"Seulement s’il touche une allocation"},{"id":"d","text":"Seulement s’il a moins de 25 ans"}],"correctChoiceId":"b","explanation":"La définition utilisée exige notamment une recherche active, ou un emploi déjà trouvé qui commence prochainement.","nuance":"Cette définition statistique ne décrit pas toutes les personnes qui souhaitent travailler.","sources":[{"publisher":"Insee","title":"Chômeur au sens du BIT","url":"https://www.insee.fr/fr/metadonnees/definition/c1129","checkedAt":"2026-10-23"}]},{"id":"q031-simple-02","prompt":"Ne pas avoir de travail suffit-il à être compté comme chômeur ?","choices":[{"id":"a","text":"Oui, sans autre condition"},{"id":"b","text":"Oui, sauf pour les étudiants"},{"id":"c","text":"Seulement si on touche le RSA"},{"id":"d","text":"Non, il faut aussi être disponible et remplir les critères de recherche"}],"correctChoiceId":"d","explanation":"L’Insee distingue emploi, chômage et inactivité. Le chômage repose sur plusieurs conditions, pas sur la seule absence d’emploi.","nuance":"« Inactif » est ici une catégorie statistique, pas un jugement sur la personne.","sources":[{"publisher":"Insee","title":"Chômeur au sens du BIT","url":"https://www.insee.fr/fr/metadonnees/definition/c1129","checkedAt":"2026-10-23"}]},{"id":"q031-simple-03","prompt":"Un retraité qui ne cherche pas d’emploi est-il compté parmi les chômeurs ?","choices":[{"id":"a","text":"Non"},{"id":"b","text":"Oui, puisqu’il n’a pas de travail"},{"id":"c","text":"Oui, s’il touche une petite retraite"},{"id":"d","text":"Seulement avant 70 ans"}],"correctChoiceId":"a","explanation":"Une personne sans emploi qui ne cherche pas à travailler ne remplit pas les critères du chômage au sens de l’Insee.","nuance":"L’exemple concerne un retraité qui ne cherche pas d’emploi, pas tous les retraités.","sources":[{"publisher":"Insee","title":"Chômeur au sens du BIT","url":"https://www.insee.fr/fr/metadonnees/definition/c1129","checkedAt":"2026-10-23"}]},{"id":"q031-simple-04","prompt":"Quelqu’un a trouvé un poste qui commence bientôt. Peut-il encore être compté au chômage ?","choices":[{"id":"a","text":"Non, dès la promesse d’embauche il est en emploi"},{"id":"b","text":"Seulement si le poste est à temps partiel"},{"id":"c","text":"Oui, sous les conditions prévues"},{"id":"d","text":"Seulement si l’employeur est public"}],"correctChoiceId":"c","explanation":"La définition prévoit le cas d’un emploi qui commence dans moins de trois mois, avec les autres conditions requises.","nuance":"Trouver un emploi et avoir déjà commencé à travailler sont deux étapes différentes.","sources":[{"publisher":"Insee","title":"Chômeur au sens du BIT","url":"https://www.insee.fr/fr/metadonnees/definition/c1129","checkedAt":"2026-10-23"}]},{"id":"q031-simple-05","prompt":"Peut-on vouloir travailler sans être compté parmi les chômeurs ?","choices":[{"id":"a","text":"Non, c’est impossible"},{"id":"b","text":"Seulement si on travaille déjà à plein temps"},{"id":"c","text":"Oui, si on ne remplit pas tous les critères"},{"id":"d","text":"Non, le chiffre couvre tous les souhaits de travail"}],"correctChoiceId":"c","explanation":"Le « halo autour du chômage » rassemble des personnes sans emploi qui souhaitent travailler mais ne remplissent pas tous les critères.","nuance":"Par exemple, elles ne sont pas disponibles assez vite ou n’ont pas recherché récemment.","sources":[{"publisher":"Insee","title":"Halo autour du chômage","url":"https://www.insee.fr/fr/metadonnees/definition/c1415","checkedAt":"2026-10-24"}]},{"id":"q031-simple-06","prompt":"Une personne découragée qui a arrêté ses recherches veut-elle forcément rester sans emploi ?","choices":[{"id":"a","text":"Non, l’arrêt des recherches ne prouve pas cela"},{"id":"b","text":"Oui, c’est la définition du découragement"},{"id":"c","text":"Oui, après un mois sans candidature"},{"id":"d","text":"Non, elle est forcément comptée au chômage"}],"correctChoiceId":"a","explanation":"On peut souhaiter un emploi sans avoir fait de recherche active récente. Le chiffre du chômage ne couvre pas toutes ces situations.","nuance":"On ne peut pas déduire les motivations d’une personne de sa seule catégorie statistique.","sources":[{"publisher":"Insee","title":"Halo autour du chômage","url":"https://www.insee.fr/fr/metadonnees/definition/c1415","checkedAt":"2026-10-24"}]},{"id":"q031-simple-07","prompt":"Une personne en petit temps partiel peut-elle vouloir travailler plus ?","choices":[{"id":"a","text":"Non, le temps partiel est toujours choisi"},{"id":"b","text":"Seulement si elle est étudiante"},{"id":"c","text":"Non, elle est forcément comptée comme chômeuse"},{"id":"d","text":"Oui, elle peut être en sous-emploi"}],"correctChoiceId":"d","explanation":"Le sous-emploi inclut notamment des personnes à temps partiel qui souhaitent travailler davantage et sont disponibles.","nuance":"Elles ont déjà un emploi : elles ne sont donc pas comptées comme chômeuses.","sources":[{"publisher":"Insee","title":"Halo autour du chômage et sous-emploi","url":"https://www.insee.fr/fr/statistiques/8376850","checkedAt":"2026-10-24"}]},{"id":"q031-simple-08","prompt":"« En emploi » veut-il forcément dire « assez d’heures pour vivre » ?","choices":[{"id":"a","text":"Oui, c’est ce que mesure l’indicateur"},{"id":"b","text":"Non, ce chiffre ne dit pas si les heures suffisent"},{"id":"c","text":"Oui, sauf pour les indépendants"},{"id":"d","text":"Non, toutes les personnes en emploi sont précaires"}],"correctChoiceId":"b","explanation":"Le classement en emploi ne renseigne pas à lui seul sur le volume d’heures souhaité ni sur le niveau de vie.","nuance":"Il faut d’autres informations pour parler de qualité de l’emploi.","sources":[{"publisher":"Insee","title":"Halo autour du chômage et sous-emploi","url":"https://www.insee.fr/fr/statistiques/8376850","checkedAt":"2026-10-24"}]},{"id":"q031-simple-09","prompt":"Le nombre de chômeurs suffit-il à mesurer tous les besoins d’emploi ?","choices":[{"id":"a","text":"Non, il faut aussi regarder le halo et le sous-emploi"},{"id":"b","text":"Oui, il regroupe toutes les personnes insatisfaites"},{"id":"c","text":"Oui, si le chiffre est national"},{"id":"d","text":"Non, il suffit de compter les retraités"}],"correctChoiceId":"a","explanation":"Ces indicateurs regardent des situations différentes : sans emploi, envie de travailler ou besoin de plus d’heures.","nuance":"On ne doit pas additionner des catégories sans vérifier leurs définitions.","sources":[{"publisher":"Insee","title":"Halo autour du chômage et sous-emploi","url":"https://www.insee.fr/fr/statistiques/8376850","checkedAt":"2026-10-24"}]},{"id":"q031-simple-10","prompt":"Un taux de chômage prouve-t-il que les gens ne veulent pas travailler ?","choices":[{"id":"a","text":"Oui, dès qu’il augmente"},{"id":"b","text":"Oui, s’il dépasse 5 %"},{"id":"c","text":"Non, il ne mesure pas cette opinion"},{"id":"d","text":"Non, il prouve que tous refusent les temps partiels"}],"correctChoiceId":"c","explanation":"Le chiffre mesure une situation définie par des critères d’emploi, de disponibilité et de recherche. Ce n’est pas un test de motivation.","nuance":"Expliquer le chômage demande aussi d’étudier les emplois disponibles et les obstacles rencontrés.","sources":[{"publisher":"Insee","title":"Chômeur au sens du BIT","url":"https://www.insee.fr/fr/metadonnees/definition/c1129","checkedAt":"2026-10-23"}]}]}','2026-10-24T11:15:00.000Z');
UPDATE quizzes SET outline='["Dans les chiffres de l’Insee, un chômeur doit-il chercher un emploi ?", "Ne pas avoir de travail suffit-il à être compté comme chômeur ?", "Un retraité qui ne cherche pas d’emploi est-il compté parmi les chômeurs ?", "Quelqu’un a trouvé un poste qui commence bientôt. Peut-il encore être compté au chômage ?", "Peut-on vouloir travailler sans être compté parmi les chômeurs ?", "Une personne découragée qui a arrêté ses recherches veut-elle forcément rester sans emploi ?", "Une personne en petit temps partiel peut-elle vouloir travailler plus ?", "« En emploi » veut-il forcément dire « assez d’heures pour vivre » ?", "Le nombre de chômeurs suffit-il à mesurer tous les besoins d’emploi ?", "Un taux de chômage prouve-t-il que les gens ne veulent pas travailler ?"]',current_version=2 WHERE id='q031';
INSERT INTO quiz_versions(quiz_id,version,body,published_at) VALUES ('q036',2,'{"title":"Mes cotisations sont mises de côté pour ma retraite","intro":"« Ma retraite, c’est mon argent mis de côté. » On regarde où vont les cotisations et ce qui ouvre des droits.","questions":[{"id":"q036-simple-01","prompt":"Dans un système par répartition, tes cotisations servent surtout à…","choices":[{"id":"a","text":"Remplir un compte d’épargne à ton nom"},{"id":"b","text":"Payer les retraites versées aujourd’hui"},{"id":"c","text":"Acheter obligatoirement des actions pour toi"},{"id":"d","text":"Financer seulement ta future maison de retraite"}],"correctChoiceId":"b","explanation":"Les cotisations des personnes qui travaillent financent les pensions actuelles. C’est le principe de la répartition.","nuance":"Cela n’empêche pas certains régimes d’avoir des réserves.","sources":[{"publisher":"Ministère du Travail","title":"Le système et les régimes de retraite","url":"https://travail-emploi.gouv.fr/retraite","checkedAt":"2026-10-23"}]},{"id":"q036-simple-02","prompt":"Existe-t-il une cagnotte personnelle contenant toutes tes cotisations retraite ?","choices":[{"id":"a","text":"Oui, avec ton nom dans une banque"},{"id":"b","text":"Oui, mais seulement après 40 ans"},{"id":"c","text":"Oui, et tu peux tout retirer librement"},{"id":"d","text":"Non, pas dans le système par répartition"}],"correctChoiceId":"d","explanation":"Les cotisations ouvrent des droits selon les règles du régime. Elles ne constituent pas un compte bancaire personnel à récupérer.","nuance":"Une épargne retraite privée suit une autre logique.","sources":[{"publisher":"Ministère du Travail","title":"Le système et les régimes de retraite","url":"https://travail-emploi.gouv.fr/retraite","checkedAt":"2026-10-23"}]},{"id":"q036-simple-03","prompt":"La capitalisation, c’est plutôt…","choices":[{"id":"a","text":"Accumuler une épargne ou des actifs pour la retraite"},{"id":"b","text":"Faire payer les pensions actuelles par les actifs"},{"id":"c","text":"Annuler toutes les cotisations"},{"id":"d","text":"Payer la même pension à tout le monde"}],"correctChoiceId":"a","explanation":"La capitalisation repose sur des sommes accumulées et placées. Elle se distingue du financement courant des pensions par répartition.","nuance":"Les deux mécanismes peuvent coexister.","sources":[{"publisher":"Ministère du Travail","title":"Le système et les régimes de retraite","url":"https://travail-emploi.gouv.fr/retraite","checkedAt":"2026-10-23"}]},{"id":"q036-simple-04","prompt":"Un régime par répartition peut-il avoir des réserves ?","choices":[{"id":"a","text":"Non, c’est interdit par définition"},{"id":"b","text":"Seulement s’il devient entièrement privé"},{"id":"c","text":"Oui"},{"id":"d","text":"Non, toute réserve appartient personnellement aux cotisants"}],"correctChoiceId":"c","explanation":"Des réserves peuvent compléter le fonctionnement d’un régime par répartition. Leur existence ne le transforme pas automatiquement en capitalisation.","nuance":"Le rôle et le montant des réserves varient selon les régimes.","sources":[{"publisher":"Conseil d’orientation des retraites","title":"Répartition, réserves et capitalisation","url":"https://www.cor-retraites.fr/reunions-du-cor/repartition-reserves-capitalisation-quels-enjeux-pour-retraites","checkedAt":"2026-10-23"}]},{"id":"q036-simple-05","prompt":"Si les cotisations ne sont pas mises de côté, servent-elles quand même à tes droits ?","choices":[{"id":"a","text":"Non, elles n’ont aucun lien avec ta retraite"},{"id":"b","text":"Seulement si tu ne changes jamais d’emploi"},{"id":"c","text":"Oui, elles participent à l’acquisition de droits"},{"id":"d","text":"Non, seule ton épargne compte"}],"correctChoiceId":"c","explanation":"Financer les pensions actuelles et ouvrir des droits pour plus tard sont deux fonctions compatibles du système.","nuance":"La pension future dépend des règles du régime et du parcours.","sources":[{"publisher":"Ministère du Travail","title":"Le système et les régimes de retraite","url":"https://travail-emploi.gouv.fr/retraite","checkedAt":"2026-10-23"}]},{"id":"q036-simple-06","prompt":"Une période de chômage peut-elle compter pour la retraite ?","choices":[{"id":"a","text":"Oui, sous certaines conditions"},{"id":"b","text":"Non, jamais"},{"id":"c","text":"Oui, sans aucune limite"},{"id":"d","text":"Seulement si on retrouve le même employeur"}],"correctChoiceId":"a","explanation":"Certaines périodes de chômage permettent de valider des trimestres et, selon la situation, d’acquérir des points.","nuance":"Les règles diffèrent selon l’indemnisation et le régime concerné.","sources":[{"publisher":"Info Retraite","title":"Chômage et droits à la retraite","url":"https://www.info-retraite.fr/portail-info/sites/PortailInformationnel/home/mes-droits-a-la-retraite/ma-vie-professionnelle-1/periode-dinactivite/chomage.html","checkedAt":"2026-10-24"}]},{"id":"q036-simple-07","prompt":"Avoir des enfants peut-il ouvrir des droits à la retraite ?","choices":[{"id":"a","text":"Non, seul le salaire compte"},{"id":"b","text":"Oui, mais uniquement si on est propriétaire"},{"id":"c","text":"Seulement si les enfants travaillent déjà"},{"id":"d","text":"Oui, selon le régime et la situation"}],"correctChoiceId":"d","explanation":"Des droits supplémentaires peuvent être liés aux enfants, par exemple des trimestres ou une majoration de pension.","nuance":"Leur attribution n’est pas identique pour tous les parents ni dans tous les régimes.","sources":[{"publisher":"Info Retraite","title":"Droits liés aux enfants","url":"https://www.info-retraite.fr/portail-info/sites/PortailInformationnel/home/mes-droits-a-la-retraite/ma-vie-personnelle-1/famille/droits-lies-aux-enfants.html","checkedAt":"2026-10-24"}]},{"id":"q036-simple-08","prompt":"La retraite dépend-elle uniquement d’une somme d’argent versée ?","choices":[{"id":"a","text":"Oui, c’est un simple remboursement"},{"id":"b","text":"Non, le parcours et des droits de solidarité comptent aussi"},{"id":"c","text":"Oui, avec le même taux de rendement pour tous"},{"id":"d","text":"Non, les cotisations ne comptent jamais"}],"correctChoiceId":"b","explanation":"Les droits ne se résument pas à une cagnotte : certaines périodes sans emploi peuvent aussi être prises en compte.","nuance":"Cela ne signifie pas que toutes les interruptions donnent les mêmes droits.","sources":[{"publisher":"Info Retraite","title":"Chômage et droits à la retraite","url":"https://www.info-retraite.fr/portail-info/sites/PortailInformationnel/home/mes-droits-a-la-retraite/ma-vie-professionnelle-1/periode-dinactivite/chomage.html","checkedAt":"2026-10-24"}]},{"id":"q036-simple-09","prompt":"Moins de cotisations encaissées, à pensions inchangées : cela pose-t-il un problème de financement ?","choices":[{"id":"a","text":"Oui, il faut compenser l’écart"},{"id":"b","text":"Non, les pensions se financent toutes seules"},{"id":"c","text":"Non, chaque retraité récupère sa cagnotte"},{"id":"d","text":"Oui, toutes les pensions s’arrêtent aussitôt"}],"correctChoiceId":"a","explanation":"À dépenses identiques, une baisse des ressources crée un besoin de financement. Plusieurs choix peuvent ensuite être discutés.","nuance":"C’est un raisonnement à paramètres constants, pas une annonce de baisse des retraites.","sources":[{"publisher":"Conseil d’orientation des retraites","title":"Répartition, réserves et capitalisation","url":"https://www.cor-retraites.fr/reunions-du-cor/repartition-reserves-capitalisation-quels-enjeux-pour-retraites","checkedAt":"2026-10-23"}]},{"id":"q036-simple-10","prompt":"« J’ai cotisé, donc la somme m’attend à la banque » : qu’est-ce qui cloche ?","choices":[{"id":"a","text":"Les cotisations ne financent aucune pension"},{"id":"b","text":"La retraite ne dépend jamais du travail"},{"id":"c","text":"Les droits à retraite ne sont pas une épargne personnelle"},{"id":"d","text":"Tous les régimes fonctionnent uniquement par capitalisation"}],"correctChoiceId":"c","explanation":"Dans la répartition, on acquiert des droits tandis que les recettes financent les pensions actuelles.","nuance":"Cela n’enlève pas l’importance des droits acquis.","sources":[{"publisher":"Ministère du Travail","title":"Le système et les régimes de retraite","url":"https://travail-emploi.gouv.fr/retraite","checkedAt":"2026-10-23"}]}]}','2026-10-24T11:15:00.000Z');
UPDATE quizzes SET outline='["Dans un système par répartition, tes cotisations servent surtout à…", "Existe-t-il une cagnotte personnelle contenant toutes tes cotisations retraite ?", "La capitalisation, c’est plutôt…", "Un régime par répartition peut-il avoir des réserves ?", "Si les cotisations ne sont pas mises de côté, servent-elles quand même à tes droits ?", "Une période de chômage peut-elle compter pour la retraite ?", "Avoir des enfants peut-il ouvrir des droits à la retraite ?", "La retraite dépend-elle uniquement d’une somme d’argent versée ?", "Moins de cotisations encaissées, à pensions inchangées : cela pose-t-il un problème de financement ?", "« J’ai cotisé, donc la somme m’attend à la banque » : qu’est-ce qui cloche ?"]',current_version=2 WHERE id='q036';
INSERT INTO quiz_versions(quiz_id,version,body,published_at) VALUES ('q041',2,'{"title":"Les immigrés touchent toutes les aides en arrivant","intro":"« Ils arrivent et touchent toutes les aides. » RSA, soins, logement : on regarde ce qui est vraiment accessible.","questions":[{"id":"q041-simple-01","prompt":"Un étranger qui arrive en France touche-t-il automatiquement le RSA ?","choices":[{"id":"a","text":"Oui, dès son arrivée"},{"id":"b","text":"Non, il y a des conditions"},{"id":"c","text":"Oui, s’il donne une adresse"},{"id":"d","text":"Oui, dès sa première demande de séjour"}],"correctChoiceId":"b","explanation":"Le RSA dépend des ressources, de l’âge et du droit au séjour. Pour beaucoup de personnes hors UE, une durée de titre autorisant le travail est aussi exigée.","nuance":"Les règles diffèrent selon le statut et la nationalité : il existe des exceptions.","sources":[{"publisher":"Service Public — DILA","title":"RSA : demandeur de 25 ans et plus — conditions et calcul","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F19778","checkedAt":"2026-10-23"}]},{"id":"q041-simple-02","prompt":"Un réfugié doit-il toujours attendre cinq ans pour demander le RSA ?","choices":[{"id":"a","text":"Oui, comme tous les étrangers"},{"id":"b","text":"Non, car il reçoit le double du RSA"},{"id":"c","text":"Oui, sauf s’il a des enfants"},{"id":"d","text":"Non, il fait partie des exceptions"}],"correctChoiceId":"d","explanation":"Une personne reconnue réfugiée n’est pas soumise à cette attente de cinq ans. Elle doit quand même remplir les autres conditions.","nuance":"Demander l’asile et avoir obtenu le statut de réfugié, ce n’est pas la même chose.","sources":[{"publisher":"Service Public — DILA","title":"RSA : demandeur de 25 ans et plus — conditions et calcul","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F19778","checkedAt":"2026-10-23"}]},{"id":"q041-simple-03","prompt":"Quelle aide peut recevoir une personne qui demande l’asile ?","choices":[{"id":"a","text":"Une allocation spécifique, l’ADA"},{"id":"b","text":"Le RSA sans condition"},{"id":"c","text":"La prime d’activité sans travailler"},{"id":"d","text":"Une allocation chômage sans avoir travaillé"}],"correctChoiceId":"a","explanation":"L’ADA est une aide destinée aux demandeurs d’asile, sous conditions. Elle ne correspond pas à un RSA automatiquement versé à l’arrivée.","nuance":"Les ressources et les conditions d’accueil comptent notamment.","sources":[{"publisher":"Service Public — DILA","title":"En quoi consiste l’allocation pour demandeur d’asile (Ada) ?","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F33314","checkedAt":"2026-10-23"}]},{"id":"q041-simple-04","prompt":"L’ADA de base pour une personne seule, c’est combien par jour ?","choices":[{"id":"a","text":"14,20 €"},{"id":"b","text":"21 €"},{"id":"c","text":"6,80 €"},{"id":"d","text":"32 €"}],"correctChoiceId":"c","explanation":"Le montant de base est de 6,80 € par jour, soit 204 € sur 30 jours. Un supplément est possible dans certains cas sans hébergement.","nuance":"Montant hors supplément, selon la fiche consultée en octobre 2026.","sources":[{"publisher":"Service Public — DILA","title":"En quoi consiste l’allocation pour demandeur d’asile (Ada) ?","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F33314","checkedAt":"2026-10-23"}]},{"id":"q041-simple-05","prompt":"Un demandeur d’asile peut-il travailler dès le début ?","choices":[{"id":"a","text":"Oui, la demande suffit"},{"id":"b","text":"Non, jamais pendant la procédure"},{"id":"c","text":"Pas en général : l’accès au travail est encadré"},{"id":"d","text":"Oui, mais seulement à temps partiel"}],"correctChoiceId":"c","explanation":"Ce statut ne donne pas immédiatement le droit de travailler. Après six mois, une autorisation peut être demandée sous conditions si l’Ofpra n’a pas répondu.","nuance":"Le point de départ du délai dépend de la date de dépôt de la demande.","sources":[{"publisher":"Service Public — DILA","title":"Accès au travail du demandeur d’asile","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F2741","checkedAt":"2026-10-23"}]},{"id":"q041-simple-06","prompt":"L’AME, c’est de l’argent versé chaque mois ?","choices":[{"id":"a","text":"Non, c’est une prise en charge de soins"},{"id":"b","text":"Oui, comme le RSA"},{"id":"c","text":"Oui, mais réservé aux médicaments"},{"id":"d","text":"Non, c’est un prêt à rembourser"}],"correctChoiceId":"a","explanation":"L’aide médicale de l’État permet l’accès à des soins. Son coût n’est pas une somme que la personne reçoit pour ses dépenses quotidiennes.","nuance":"Elle concerne des personnes en situation irrégulière qui remplissent ses conditions.","sources":[{"publisher":"Service Public — DILA","title":"Qu’est-ce que l’aide médicale de l’État (AME) ?","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F3079","checkedAt":"2026-10-23"}]},{"id":"q041-simple-07","prompt":"Un adulte sans titre de séjour a-t-il l’AME dès son arrivée ?","choices":[{"id":"a","text":"Oui, sans démarche"},{"id":"b","text":"Oui, avec un passeport valide"},{"id":"c","text":"Non, il faut cinq années de cotisations"},{"id":"d","text":"Pas en général, des conditions s’appliquent"}],"correctChoiceId":"d","explanation":"Il faut notamment une durée de résidence et des ressources sous un plafond. L’accès n’est pas automatique le jour de l’arrivée.","nuance":"Les mineurs et les soins urgents ont des règles particulières.","sources":[{"publisher":"Service Public — DILA","title":"Qu’est-ce que l’aide médicale de l’État (AME) ?","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F3079","checkedAt":"2026-10-23"}]},{"id":"q041-simple-08","prompt":"Être étranger suffit-il pour toucher l’APL ?","choices":[{"id":"a","text":"Oui, c’est une aide réservée aux étrangers"},{"id":"b","text":"Non, il faut remplir plusieurs conditions"},{"id":"c","text":"Non, seuls les Français y ont droit"},{"id":"d","text":"Oui, pendant la première année"}],"correctChoiceId":"b","explanation":"L’APL dépend notamment du logement, des ressources et du droit au séjour. La nationalité étrangère ne crée pas un droit automatique.","nuance":"Les règles de séjour diffèrent entre citoyens européens et autres nationalités.","sources":[{"publisher":"Service Public — DILA","title":"Aide personnalisée au logement (APL)","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F12006","checkedAt":"2026-10-23"}]},{"id":"q041-simple-09","prompt":"Pour les allocations familiales, une adresse en France suffit-elle ?","choices":[{"id":"a","text":"Non, d’autres conditions sont à remplir"},{"id":"b","text":"Oui, dès le premier jour"},{"id":"c","text":"Oui, dès qu’un enfant est scolarisé"},{"id":"d","text":"Non, il faut obligatoirement être français"}],"correctChoiceId":"a","explanation":"Pour un parent étranger, les conditions liées au séjour et à la situation des enfants comptent aussi. Une adresse ne remplace pas ces vérifications.","nuance":"Les justificatifs varient selon les situations.","sources":[{"publisher":"Service Public — DILA","title":"Un étranger peut-il percevoir des prestations familiales en France ?","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F2787","checkedAt":"2026-10-23"}]},{"id":"q041-simple-10","prompt":"Ces règles prouvent-elles pourquoi les gens immigrent ?","choices":[{"id":"a","text":"Oui, puisqu’il existe des aides"},{"id":"b","text":"Oui, si une personne touche le RSA"},{"id":"c","text":"Non, elles décrivent des droits, pas des motivations"},{"id":"d","text":"Elles prouvent que personne ne pense aux aides"}],"correctChoiceId":"c","explanation":"Savoir qu’une aide existe ne dit pas pourquoi quelqu’un est parti de son pays. Pour parler des motivations, il faut d’autres données.","nuance":"Ce quiz vérifie l’accès aux aides, pas toutes les causes de l’immigration.","sources":[{"publisher":"Insee","title":"Définition : immigré","url":"https://www.insee.fr/fr/metadonnees/definition/c1328","checkedAt":"2026-10-23"},{"publisher":"Service Public — DILA","title":"Un étranger peut-il percevoir des prestations familiales en France ?","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F2787","checkedAt":"2026-10-23"}]}]}','2026-10-24T11:15:00.000Z');
UPDATE quizzes SET outline='["Un étranger qui arrive en France touche-t-il automatiquement le RSA ?", "Un réfugié doit-il toujours attendre cinq ans pour demander le RSA ?", "Quelle aide peut recevoir une personne qui demande l’asile ?", "L’ADA de base pour une personne seule, c’est combien par jour ?", "Un demandeur d’asile peut-il travailler dès le début ?", "L’AME, c’est de l’argent versé chaque mois ?", "Un adulte sans titre de séjour a-t-il l’AME dès son arrivée ?", "Être étranger suffit-il pour toucher l’APL ?", "Pour les allocations familiales, une adresse en France suffit-elle ?", "Ces règles prouvent-elles pourquoi les gens immigrent ?"]',current_version=2 WHERE id='q041';
INSERT INTO quiz_versions(quiz_id,version,body,published_at) VALUES ('q042',2,'{"title":"Immigré et étranger, c’est la même chose","intro":"« Immigré » et « étranger » : on les mélange souvent. Dix situations concrètes pour savoir de qui on parle.","questions":[{"id":"q042-simple-01","prompt":"Une personne immigrée peut-elle être française ?","choices":[{"id":"a","text":"Non, les deux mots s’opposent"},{"id":"b","text":"Oui, si elle a acquis la nationalité française"},{"id":"c","text":"Seulement si elle est née en France"},{"id":"d","text":"Non, elle cesse alors d’avoir immigré"}],"correctChoiceId":"b","explanation":"Pour l’Insee, une personne née étrangère à l’étranger et vivant en France reste immigrée même après être devenue française.","nuance":"« Immigré » décrit une situation à la naissance et un parcours, pas la nationalité actuelle.","sources":[{"publisher":"Insee","title":"Définition : immigré","url":"https://www.insee.fr/fr/metadonnees/definition/c1328","checkedAt":"2026-10-23"}]},{"id":"q042-simple-02","prompt":"Un étranger, au sens de l’Insee, est quelqu’un qui…","choices":[{"id":"a","text":"Est forcément né à l’étranger"},{"id":"b","text":"Vient de s’installer en France"},{"id":"c","text":"Parle une autre langue chez lui"},{"id":"d","text":"Vit en France sans avoir la nationalité française"}],"correctChoiceId":"d","explanation":"La définition repose sur la nationalité actuelle. Le lieu de naissance ne suffit donc pas.","nuance":"Une personne étrangère peut être née en France.","sources":[{"publisher":"Insee","title":"Définition : immigré","url":"https://www.insee.fr/fr/metadonnees/definition/c1328","checkedAt":"2026-10-23"},{"publisher":"Insee","title":"Définition : étranger","url":"https://www.insee.fr/fr/metadonnees/definition/c1198","checkedAt":"2026-10-23"}]},{"id":"q042-simple-03","prompt":"Née au Maroc, de nationalité marocaine, puis devenue française : immigrée ?","choices":[{"id":"a","text":"Oui, si elle vit en France"},{"id":"b","text":"Non, puisqu’elle est française"},{"id":"c","text":"Seulement pendant ses cinq premières années en France"},{"id":"d","text":"Seulement si ses parents vivent encore au Maroc"}],"correctChoiceId":"a","explanation":"Elle est née étrangère à l’étranger : acquérir ensuite la nationalité française ne change pas ce classement statistique.","nuance":"Cela ne diminue en rien sa nationalité française.","sources":[{"publisher":"Insee","title":"Définition : immigré","url":"https://www.insee.fr/fr/metadonnees/definition/c1328","checkedAt":"2026-10-23"}]},{"id":"q042-simple-04","prompt":"Né en France, sans nationalité française : étranger ?","choices":[{"id":"a","text":"Non, le lieu de naissance suffit à dire non"},{"id":"b","text":"Seulement après 18 ans"},{"id":"c","text":"Oui"},{"id":"d","text":"Seulement si ses parents sont arrivés récemment"}],"correctChoiceId":"c","explanation":"Dans la situation décrite, la personne n’a pas la nationalité française. Elle est donc étrangère au sens de cette définition.","nuance":"La question décrit une nationalité donnée ; elle ne résume pas les règles d’accès à la nationalité.","sources":[{"publisher":"Insee","title":"Définition : immigré","url":"https://www.insee.fr/fr/metadonnees/definition/c1328","checkedAt":"2026-10-23"},{"publisher":"Insee","title":"Définition : étranger","url":"https://www.insee.fr/fr/metadonnees/definition/c1198","checkedAt":"2026-10-23"}]},{"id":"q042-simple-05","prompt":"Cette même personne née en France est-elle immigrée ?","choices":[{"id":"a","text":"Oui, puisqu’elle est étrangère"},{"id":"b","text":"Oui, si ses parents sont immigrés"},{"id":"c","text":"Non, elle n’est pas née à l’étranger"},{"id":"d","text":"Seulement si elle parle deux langues"}],"correctChoiceId":"c","explanation":"La définition d’immigré exige d’être né étranger à l’étranger. Être étranger aujourd’hui ne suffit pas.","nuance":"On peut donc être étranger sans être immigré.","sources":[{"publisher":"Insee","title":"Définition : immigré","url":"https://www.insee.fr/fr/metadonnees/definition/c1328","checkedAt":"2026-10-23"}]},{"id":"q042-simple-06","prompt":"Née à l’étranger avec la nationalité française, puis installée en France : immigrée ?","choices":[{"id":"a","text":"Non, pas selon la définition de l’Insee"},{"id":"b","text":"Oui, toute naissance à l’étranger suffit"},{"id":"c","text":"Oui, si elle parle une autre langue"},{"id":"d","text":"Seulement si elle est née hors d’Europe"}],"correctChoiceId":"a","explanation":"Il faut être né étranger à l’étranger pour entrer dans cette définition. Cette personne était française dès sa naissance.","nuance":"Le langage courant peut utiliser « immigration » dans un sens différent.","sources":[{"publisher":"Insee","title":"Définition : immigré","url":"https://www.insee.fr/fr/metadonnees/definition/c1328","checkedAt":"2026-10-23"}]},{"id":"q042-simple-07","prompt":"Avoir des parents immigrés suffit-il à être soi-même immigré ?","choices":[{"id":"a","text":"Oui, automatiquement"},{"id":"b","text":"Oui, jusqu’à la troisième génération"},{"id":"c","text":"Seulement si les deux parents sont immigrés"},{"id":"d","text":"Non, le lieu et la nationalité de naissance comptent"}],"correctChoiceId":"d","explanation":"Une personne née en France n’est pas immigrée au sens de l’Insee, même si ses parents le sont.","nuance":"Le parcours des parents et celui de leur enfant sont deux choses distinctes.","sources":[{"publisher":"Insee","title":"Définition : immigré","url":"https://www.insee.fr/fr/metadonnees/definition/c1328","checkedAt":"2026-10-23"}]},{"id":"q042-simple-08","prompt":"Une personne franco-italienne est-elle étrangère en France ?","choices":[{"id":"a","text":"Oui, parce qu’elle a deux nationalités"},{"id":"b","text":"Non, elle possède la nationalité française"},{"id":"c","text":"Seulement si elle utilise son passeport italien"},{"id":"d","text":"Oui, si elle est née en Italie"}],"correctChoiceId":"b","explanation":"L’Insee ne classe pas parmi les étrangers les personnes qui ont la nationalité française et une autre nationalité.","nuance":"La double nationalité ne signifie pas une nationalité française partielle.","sources":[{"publisher":"Insee","title":"Définition : immigré","url":"https://www.insee.fr/fr/metadonnees/definition/c1328","checkedAt":"2026-10-23"},{"publisher":"Insee","title":"Définition : étranger","url":"https://www.insee.fr/fr/metadonnees/definition/c1198","checkedAt":"2026-10-23"}]},{"id":"q042-simple-09","prompt":"Le nombre d’étrangers mesure-t-il les arrivées de l’année ?","choices":[{"id":"a","text":"Non, il décrit des personnes présentes, pas un flux d’arrivées"},{"id":"b","text":"Oui, c’est exactement le même chiffre"},{"id":"c","text":"Oui, si on le mesure au 1er janvier"},{"id":"d","text":"Non, il compte seulement les touristes"}],"correctChoiceId":"a","explanation":"Des personnes étrangères peuvent résider en France depuis longtemps. Un effectif à une date ne mesure pas les nouvelles arrivées.","nuance":"Il faut distinguer présence sur le territoire et mouvements pendant une période.","sources":[{"publisher":"Insee","title":"Définition : immigré","url":"https://www.insee.fr/fr/metadonnees/definition/c1328","checkedAt":"2026-10-23"},{"publisher":"Insee","title":"Définition : étranger","url":"https://www.insee.fr/fr/metadonnees/definition/c1198","checkedAt":"2026-10-23"}]},{"id":"q042-simple-10","prompt":"Un prénom suffit-il à savoir si quelqu’un est immigré ?","choices":[{"id":"a","text":"Oui, si le prénom vient d’un autre pays"},{"id":"b","text":"Oui, avec son accent en plus"},{"id":"c","text":"Non, il faut connaître les critères de la définition"},{"id":"d","text":"Seulement si le nom est aussi étranger"}],"correctChoiceId":"c","explanation":"La définition repose sur le pays et la nationalité à la naissance, ainsi que la résidence en France. Un prénom ne donne pas ces informations.","nuance":"On ne peut pas déduire le statut d’une personne de son apparence ou de son nom.","sources":[{"publisher":"Insee","title":"Définition : étranger","url":"https://www.insee.fr/fr/metadonnees/definition/c1198","checkedAt":"2026-10-23"}]}]}','2026-10-24T11:15:00.000Z');
UPDATE quizzes SET outline='["Une personne immigrée peut-elle être française ?", "Un étranger, au sens de l’Insee, est quelqu’un qui…", "Née au Maroc, de nationalité marocaine, puis devenue française : immigrée ?", "Né en France, sans nationalité française : étranger ?", "Cette même personne née en France est-elle immigrée ?", "Née à l’étranger avec la nationalité française, puis installée en France : immigrée ?", "Avoir des parents immigrés suffit-il à être soi-même immigré ?", "Une personne franco-italienne est-elle étrangère en France ?", "Le nombre d’étrangers mesure-t-il les arrivées de l’année ?", "Un prénom suffit-il à savoir si quelqu’un est immigré ?"]',current_version=2 WHERE id='q042';
INSERT INTO quiz_versions(quiz_id,version,body,published_at) VALUES ('q076',2,'{"title":"Le RN n’est plus d’extrême droite","intro":"« Le RN a changé, ce n’est plus l’extrême droite. » On regarde son classement, ses propositions et ses alliances, sans confondre le parti et ses électeurs.","questions":[{"id":"q076-simple-01","prompt":"Pour les municipales de 2026, dans quel bloc le RN était-il classé ?","choices":[{"id":"a","text":"Droite"},{"id":"b","text":"Extrême droite"},{"id":"c","text":"Centre"},{"id":"d","text":"Sans classement"}],"correctChoiceId":"b","explanation":"La décision du Conseil d’État du 27 février 2026 mentionne bien ce classement. Ce n’est donc pas seulement une étiquette utilisée par ses adversaires.","nuance":"Ce passage figure dans une décision qui traite notamment du recours de l’UDR.","sources":[{"publisher":"Conseil d’État","title":"Décision n° 512694 du 27 février 2026 — rattachement de l’UDR et classement du RN mentionné dans les motifs","url":"https://www.conseil-etat.fr/fr/arianeweb/CE/decision/2026-02-27/512694","checkedAt":"2026-10-23"}]},{"id":"q076-simple-02","prompt":"En 2024, le RN avait contesté ce classement. A-t-il gagné ?","choices":[{"id":"a","text":"Oui, il a été classé à droite"},{"id":"b","text":"Oui, tous les classements ont été supprimés"},{"id":"c","text":"Le juge n’a pas rendu de décision"},{"id":"d","text":"Non, son recours a été rejeté"}],"correctChoiceId":"d","explanation":"Le Conseil d’État a rejeté son recours le 11 mars 2024. Le classement contesté pour les sénatoriales de 2023 a été maintenu.","nuance":"Il s’agit d’un classement administratif, pas d’une condamnation pénale.","sources":[{"publisher":"Conseil d’État","title":"Décision n° 488378 du 11 mars 2024 — paragraphes 5 à 7","url":"https://www.conseil-etat.fr/fr/arianeweb/CE/decision/2024-03-11/488378","checkedAt":"2026-10-23"}]},{"id":"q076-simple-03","prompt":"Un parti choisit-il lui-même son classement officiel ?","choices":[{"id":"a","text":"Non, pas à lui seul"},{"id":"b","text":"Oui, son nom suffit"},{"id":"c","text":"Oui, s’il dépasse 5 % des voix"},{"id":"d","text":"Ce sont les instituts de sondage qui choisissent"}],"correctChoiceId":"a","explanation":"Un candidat choisit comment il se présente. L’administration lui attribue aussi une catégorie pour regrouper les résultats, qui peut être différente.","nuance":"La façon dont un parti se décrit n’est qu’un élément à examiner.","sources":[{"publisher":"Vie publique — DILA","title":"Municipales 2026 : la circulaire pour l’attribution des nuances","url":"https://www.vie-publique.fr/en-bref/301970-municipales-2026-la-circulaire-pour-lattribution-des-nuances","checkedAt":"2026-10-23"}]},{"id":"q076-simple-04","prompt":"En 2022, la « priorité nationale » proposée concernait quoi ?","choices":[{"id":"a","text":"Seulement l’armée"},{"id":"b","text":"Seulement les visas touristiques"},{"id":"c","text":"L’emploi, le logement et les aides sociales"},{"id":"d","text":"Seulement les marchés de défense"}],"correctChoiceId":"c","explanation":"Ces trois domaines figurent dans la déclaration de campagne de Marine Le Pen. La proposition touche donc aussi la vie quotidienne.","nuance":"C’est le programme de 2022, pas une mesure appliquée ni un programme pour 2027.","sources":[{"publisher":"CNCCEP — archive officielle de campagne","title":"Marine Le Pen — déclaration présidentielle 2022 (document de la candidate)","url":"https://www.cnccep.fr/pdfs/Candidat-06-Marine-Le-Pen-Declaration-accessible.pdf","checkedAt":"2026-10-23"}]},{"id":"q076-simple-05","prompt":"La « priorité nationale » départage les gens selon quoi ?","choices":[{"id":"a","text":"Leur revenu uniquement"},{"id":"b","text":"Leur ancienneté dans le logement"},{"id":"c","text":"Leur nationalité"},{"id":"d","text":"Leur nombre d’enfants uniquement"}],"correctChoiceId":"c","explanation":"Introduire une priorité de nationalité change le critère de choix, même entre deux personnes aux besoins semblables.","nuance":"Un étranger peut vivre et travailler légalement en France.","sources":[{"publisher":"CNCCEP — archive officielle de campagne","title":"Marine Le Pen — déclaration présidentielle 2022 (document de la candidate)","url":"https://www.cnccep.fr/pdfs/Candidat-06-Marine-Le-Pen-Declaration-accessible.pdf","checkedAt":"2026-10-23"},{"publisher":"Service Public — DILA","title":"Un étranger peut-il percevoir des prestations familiales en France ?","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F2787","checkedAt":"2026-10-23"}]},{"id":"q076-simple-06","prompt":"Le programme de 2022 parlait-il aussi de pouvoir d’achat ?","choices":[{"id":"a","text":"Oui, avec des propositions fiscales et sociales"},{"id":"b","text":"Non, seulement d’immigration"},{"id":"c","text":"Seulement pour les entreprises"},{"id":"d","text":"Seulement pour les retraités"}],"correctChoiceId":"a","explanation":"Le document contient aussi des propositions sur les taxes et les retraites. La présence de mesures sociales ne suffit pas à classer tout un parti.","nuance":"Une promesse ne prouve pas qu’une mesure sera efficace ou financée.","sources":[{"publisher":"CNCCEP — archive officielle de campagne","title":"Marine Le Pen — déclaration présidentielle 2022 (document de la candidate)","url":"https://www.cnccep.fr/pdfs/Candidat-06-Marine-Le-Pen-Declaration-accessible.pdf","checkedAt":"2026-10-23"}]},{"id":"q076-simple-07","prompt":"Quel groupe européen Jordan Bardella a-t-il rejoint en 2024 ?","choices":[{"id":"a","text":"Parti populaire européen"},{"id":"b","text":"Renew Europe"},{"id":"c","text":"Verts/Alliance libre européenne"},{"id":"d","text":"Patriotes pour l’Europe"}],"correctChoiceId":"d","explanation":"Le Parlement européen indique son appartenance aux Patriotes pour l’Europe, qu’il préside depuis juillet 2024. Les alliances éclairent aussi le positionnement d’un parti.","nuance":"Le nom du groupe ne résume pas toutes les positions de ses membres.","sources":[{"publisher":"Parlement européen","title":"Jordan Bardella — historique de la 10e législature","url":"https://www.europarl.europa.eu/meps/fr/131580/JORDAN_BARDELLA/history/10","checkedAt":"2026-10-23"}]},{"id":"q076-simple-08","prompt":"Peut-on limiter les aides aux étrangers sans aucune limite juridique ?","choices":[{"id":"a","text":"Oui, si c’est promis pendant une campagne"},{"id":"b","text":"Non, certaines restrictions ont été censurées"},{"id":"c","text":"Oui, dès qu’il s’agit d’étrangers"},{"id":"d","text":"Non, aucune condition de séjour n’est possible"}],"correctChoiceId":"b","explanation":"En avril 2024, le Conseil constitutionnel a jugé une restriction précise excessive. Les règles proposées doivent aussi respecter la Constitution.","nuance":"Cette décision ne portait pas sur tout le programme du RN.","sources":[{"publisher":"Conseil constitutionnel — Légifrance","title":"Décision n° 2024-6 RIP du 11 avril 2024 — accès aux prestations sociales des étrangers","url":"https://www.legifrance.gouv.fr/juri/id/CONSTEXT000049424617","checkedAt":"2026-10-23"}]},{"id":"q076-simple-09","prompt":"Un programme sur un site officiel, c’est une promesse validée ?","choices":[{"id":"a","text":"Non, c’est une trace de ce qui a été proposé"},{"id":"b","text":"Oui, son coût a été approuvé"},{"id":"c","text":"Oui, si le candidat était au second tour"},{"id":"d","text":"Non, le texte ne permet rien de vérifier"}],"correctChoiceId":"a","explanation":"L’archive permet de vérifier la promesse. Elle ne garantit ni ses résultats, ni son financement, ni sa légalité.","nuance":"L’institution qui conserve un programme ne l’approuve pas pour autant.","sources":[{"publisher":"CNCCEP — archive officielle de campagne","title":"Marine Le Pen — déclaration présidentielle 2022 (document de la candidate)","url":"https://www.cnccep.fr/pdfs/Candidat-06-Marine-Le-Pen-Declaration-accessible.pdf","checkedAt":"2026-10-23"}]},{"id":"q076-simple-10","prompt":"Le classement d’un parti dit-il pourquoi chacun vote pour lui ?","choices":[{"id":"a","text":"Oui, tous soutiennent chaque proposition"},{"id":"b","text":"Oui, au-delà de 20 % des voix"},{"id":"c","text":"Non, les motivations peuvent varier"},{"id":"d","text":"Non, personne ne vote pour un programme"}],"correctChoiceId":"c","explanation":"Un classement décrit un parti ou ses candidatures, pas les raisons de chaque électeur. Il ne permet pas de leur attribuer une intention unique.","nuance":"On peut examiner un parti sans faire le portrait de tous ses électeurs.","sources":[{"publisher":"Conseil d’État","title":"Décision n° 488378 du 11 mars 2024 — paragraphes 5 à 7","url":"https://www.conseil-etat.fr/fr/arianeweb/CE/decision/2024-03-11/488378","checkedAt":"2026-10-23"}]}]}','2026-10-24T11:15:00.000Z');
UPDATE quizzes SET outline='["Pour les municipales de 2026, dans quel bloc le RN était-il classé ?", "En 2024, le RN avait contesté ce classement. A-t-il gagné ?", "Un parti choisit-il lui-même son classement officiel ?", "En 2022, la « priorité nationale » proposée concernait quoi ?", "La « priorité nationale » départage les gens selon quoi ?", "Le programme de 2022 parlait-il aussi de pouvoir d’achat ?", "Quel groupe européen Jordan Bardella a-t-il rejoint en 2024 ?", "Peut-on limiter les aides aux étrangers sans aucune limite juridique ?", "Un programme sur un site officiel, c’est une promesse validée ?", "Le classement d’un parti dit-il pourquoi chacun vote pour lui ?"]',current_version=2 WHERE id='q076';
